def _find_pacification_target(self, content, name: str) -> Optional[str]:
    """Resolve living canonical 内乱 leader still needing 自新受抚 (敌对/潜伏 only)."""
    matched = None
    if name in content.characters:
        matched = name
    else:
        matched = next((
            key for key, character in content.characters.items()
            if name in (character.aliases or [])
        ), None)
    if not matched:
        return None
    row = self.conn.execute(
        "SELECT status, power_id FROM characters WHERE name=?", (matched,),
    ).fetchone()
    if row is None or row["status"] != "active" or row["power_id"] in (None, "ming"):
        return None
    power = self.conn.execute(
        "SELECT kind, leader, stance FROM powers WHERE id=?", (row["power_id"],),
    ).fetchone()
    if power is None or not (
        power["kind"] == "内乱"
        and power["stance"] in {"敌对", "潜伏"}
        and power["leader"] == matched
    ):
        return None
    return matched

def effect_origin_rejection(self, origin_ref: str) -> Dict[str, object] | None:
    """Authorize extractor provenance immediately before a durable write.

    When apply_score_extraction arms ``_batch_authorized_open_affair_ids``,
    ``affair:<id>`` must also sit in that frozen batch set — one authority
    for every durable-effect carrier (fiscal included).
    """
    value = str(origin_ref or "").strip()
    valid = value == "盘面自发"
    unauthorized_batch = False
    if value.startswith("dossier:"):
        try:
            dossier_id = int(value.split(":", 1)[1])
            valid = dossier_id > 0 and self.get_decree_dossier(dossier_id) is not None \
                and self.dossier_authorizes_effects(dossier_id)
        except (OverflowError, TypeError, ValueError):
            valid = False
    elif value.startswith("affair:"):
        try:
            from ming_sim.entities.affair.store import (
                UnauthorizedAffairOriginRef,
                parse_origin_ref,
            )
            kind, affair_id = parse_origin_ref(value)
            if kind == "affair" and affair_id is not None:
                self.affairs.get(int(affair_id))
                authorized = getattr(self, "_batch_authorized_open_affair_ids", None)
                if authorized is not None and affair_id not in authorized:
                    valid = False
                    unauthorized_batch = True
                else:
                    valid = True
            else:
                valid = False
        except (KeyError, OverflowError, TypeError, ValueError):
            valid = False
    if valid:
        return None
    if unauthorized_batch:
        from ming_sim.entities.affair.store import UnauthorizedAffairOriginRef
        return {
            "rejected": True,
            # Distinct from missing/invalid existence — strategic preflight
            # must not envelope-fail this; apply paths still reject itemwise.
            "category": "unauthorized_affair_origin",
            "reason": str(UnauthorizedAffairOriginRef()),
        }
    return {
        "rejected": True,
        "category": "missing_origin_ref" if not value else "invalid_origin_ref",
        "reason": ("效果缺 origin_ref；盘面自然演化须显式标为「盘面自发」"
                   if not value else f"origin_ref 非法：{value}"),
    }

def _validate_promulgation_verdict_item(
    row: object, db: GameDB,
    *,
    proposed_modes: Optional[Dict[int, str]] = None,
    prepared_context: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    """The single shape/identity authority for one provider verdict."""
    if not isinstance(row, dict):
        raise LLMContractError("颁布判决须为对象")
    if str(row.get("decision") or "") not in {"promulgated", "rejected"}:
        raise LLMContractError("颁布判决 decision 只能为 promulgated 或 rejected")
    dossier_id = row.get("dossier_id")
    if (isinstance(dossier_id, bool) or not isinstance(dossier_id, int)
            or not 0 < dossier_id <= 2 ** 63 - 1):
        raise LLMContractError("颁布判决 dossier_id 必须为有效 SQLite 正整数")

    context = prepared_context or {}
    if prepared_context is not None:
        faction_names = {
            str(item["name"]) for item in context.get("factions", [])
            if isinstance(item, dict)
        }
        class_names = {str(item) for item in context.get("classes", [])}
        gatekeeper_ids = {
            str(item["name"]) for item in context.get("gatekeepers", [])
            if isinstance(item, dict) and isinstance(item.get("name"), str)
        }
        context_dossiers = {
            int(item["id"]): item for item in context.get("dossiers", [])
            if isinstance(item, dict) and isinstance(item.get("id"), int)
        }
    else:
        faction_names = {
            str(item["name"]) for item in db.conn.execute("SELECT name FROM factions")
        }
        class_names = {
            str(item["name"])
            for item in db.conn.execute("SELECT DISTINCT name FROM classes")
        }
        gatekeeper_ids = {
            str(item["name"])
            for item in db.conn.execute("SELECT name FROM characters")
        }
        context_dossiers = {}

    modes = proposed_modes or {}
    rejection_only_fields = {
        "blocked_layer", "primary_opponents", "gatekeeper_id", "reason",
        "criteria_snapshot", "midzhi_unpromulgatable",
    }
    try:
        decision = row.get("decision")
