def _situation_terminal_effects(kind: str, severity: int, polarity: str):
    """situation 终结一锤子永久效果。按 severity 推量级（轻 50 / 中 65 / 重 80）。
    resolve：达成（bar→100）落永久回血/加成，所有 situation 都有。
    fail：仅「会崩坏」局势（_COLLAPSIBLE_KINDS）有，崩坏（bar→0）落永久重创，幅度重于回血。
    民心/皇威由 kind 倾向决定（边事/外族偏皇威，灾害/民变偏民心，余者两者兼得）。"""
    mag = 1 if severity < 55 else (2 if severity < 70 else 3)
    if kind in ("外族", "边事", "友邦", "归附", "盟约", "战机", "敌乱"):
        axis = "皇威"
    elif kind in ("天灾", "灾情", "饥荒", "人祸", "兵变", "流寇", "民变", "抗税", "丰收", "祥瑞", "民和"):
        axis = "民心"
    else:
        axis = "both"

    def _metrics(amount: int) -> Dict[str, int]:
        if axis == "both":
            half = max(1, abs(amount) // 2)
            s = 1 if amount > 0 else -1
            return {"民心": s * half, "皇威": s * half}
        return {axis: amount}

    resolve_amt = (3 if polarity == "neg" else 4) * mag
    effect_resolve = {"metrics": _metrics(resolve_amt)}
    effect_fail = {"metrics": _metrics(-5 * mag)} if kind in _COLLAPSIBLE_KINDS else {}
    return effect_resolve, effect_fail

def _strip_controlled_namespace(text: str, namespace: str) -> str:
    """Strip only the extractor's exact namespace wrappers, never prose."""
    if text.startswith("@"):
        return text[1:]
    prefix = f"{namespace}."
    if text.startswith(prefix):
        return text[len(prefix):]
    return text

def _apply_decided_triad(
    db: Any, state: Any, row: Dict[str, object], choice: Dict[str, object], *, content: Any,
) -> None:
    event_id = str(row.get("event_id") or "")
    raw_id = event_id.split(":", 1)[1] if ":" in event_id else ""
    if not raw_id.isdigit():
        return
    dossier_id = int(raw_id)
    dossier = db.get_decree_dossier(dossier_id)
    if dossier is None or not dossier.get("rescript_pending"):
        return
    decision = str(
        choice.get("dossier_decision") or choice.get("action") or ""
    ).strip()
    if decision not in {"force_promulgated", "withdrawn", "hold"}:
        return
    db.apply_dossier_promulgation(
        state, dossier_id, decision, content=content,
    )

def run_tick(name, st, p, actions, expect=None):
    print(f"\n{'='*64}\n{name}\n{'='*64}")
    for rq in ('三饷应征','火耗率','逋赋率','起运定额','Due'):   # 必填参数 presence 检查(gemini R2:原缺失走 KeyError;
        if rq not in p: raise ValueError(f"param {rq} 缺失")      # 不给默认0——火耗率缺省成0=静默改经济学,fail-loud)
    for sk in (*CASH_KEYS, *CLAIM_KEYS, '官民田', '隐田'):       # 开账显式 None 前置拦(gemini R2:float(None) TypeError 早于守门)
        if sk in st and st[sk] is None: raise ValueError(f"开账 stock {sk} 为 None")
    cash = {k: float(st.get(k,0)) for k in CASH_KEYS}
    claim = {k: float(st.get(k,0)) for k in CLAIM_KEYS}
    官民田 = float(st.get('官民田',0)); 隐田 = float(st.get('隐田',0))
    地0 = 官民田 + 隐田                                  # 土地守恒锚:清丈只重分类,总亩数不变
    cash0 = sum(cash.values()); C0 = {k: cash[k] for k in CASH_KEYS if k.startswith('C_')}
    claim0 = dict(claim)
    cash_in = cash_out = 0.0
    r = dict(实征=0,火耗实收=0,清欠=0,拨付gross=0,起运到京=0,实付=0,偿旧欠=0,行政补饷=0,
             漂没=0,中饱=0,民欠新增=0,蠲免=0,unmet_relief=0,
             NewDebt={'军饷欠':0,'官俸欠':0,'宗禄欠':0},Repaid={'军饷欠':0,'官俸欠':0,'宗禄欠':0},
             action还={'军饷欠':0})

    def xfer_internal(frm, to, amount, eff=1.0):
        """CASH 内部 3-way 转移:source减=target增+C_eff损耗增。frm/to 均 CASH。"""
        actual = min(amount, cash[frm]); cash[frm] -= actual
        got = actual*eff; loss = actual*(1-eff)
        cash[to] += got
        if loss > 0: cash['C_eff损耗'] += loss
        return actual

    # ── ⓪ action phase:先收集→算 k→按 k 执行(transfer 此时执行)──
    for a in actions:                                   # 输入校验 fail-loud(codex r16 / Fable:NaN/inf + 0-cost清丈)
        if 'type' not in a: raise ValueError(f"action 缺 type: {a}")
        for nf in ('cost','amount','挖隐田','eff'):      # NaN/inf/非数值 入口拦截(nan<0=False、str 比较 TypeError 均穿守门)
            v = a.get(nf)
            if v is None: continue
            if isinstance(v, bool) or not isinstance(v, (int, float)): raise ValueError(f"{nf} 非数值: {a}")
            if not math.isfinite(float(v)): raise ValueError(f"{nf} 非有限值(NaN/inf): {a}")
        if a['type'] not in KNOWN_ACTIONS: raise ValueError(f"unknown action: {a['type']}")
        if a.get('cost',0) < 0 or a.get('amount',0) < 0 or a.get('挖隐田',0) < 0: raise ValueError(f"负 cost/amount/挖隐田: {a}")
        if not (0 <= a.get('eff',1.0) <= 1): raise ValueError(f"eff 越界: {a}")
        if a['type'] == '补饷' and a.get('amount',0) != 0: raise ValueError(f"补饷不接受 amount(cost即支付): {a}")
        if a['type'] in ('清欠','蠲免','追赃','挪借火耗') and a.get('cost',0) != 0:
            raise ValueError(f"{a['type']} 禁带 cost(征收/转移类按 §9,否则幽灵预算压 k): {a}")
        if a['type'] in ('清丈','营建') and a.get('cost',0) <= 0:    # 行政成本类必须 cost>0(否则免费抬税基=违P3爽感)
            raise ValueError(f"{a['type']} 必须 cost>0(行政成本类): {a}")
    for rk in ('火耗率','逋赋率','漂没率','中饱率'):
        rv = p.get(rk, 0)                                # 字符串/bool 率值原在比较处 TypeError(gemini R3);bool 是 int 子类须显式拒
        if isinstance(rv, bool) or not isinstance(rv, (int, float)): raise ValueError(f"{rk} 非数值")
        if not (0 <= rv <= 1): raise ValueError(f"{rk} 越界")
    for pk in ('正赋应征','三饷应征','起运定额','拨付gross','正赋亩额'):  # param 量纲负/非有限 fail-loud(r21/opus 负值;ship-adv NaN/inf 同拦)
        v = p.get(pk)
        if v is not None:
            if isinstance(v, bool) or not isinstance(v, (int, float)): raise ValueError(f"param {pk} 非数值")
            if not math.isfinite(float(v)): raise ValueError(f"param {pk} 非有限值(NaN/inf)")
            if v < 0: raise ValueError(f"param {pk} 为负")
        elif pk in p and pk != '正赋应征':                  # 仅 正赋应征 可 None=走亩额派生;其余显式 None 拒(防 TypeError 半程崩)
            raise ValueError(f"param {pk} 为 None(仅 正赋应征 可 None)")
    for hk,dv in p.get('Due',{}).items():               # NaN Due→min(Pool,nan)=Pool 整池付给 NaN 且五层全过(ship-adv 实测)
        if hk not in ('军饷','官俸','宗禄','赈济'):       # 拼错科目=settlement+oracle 一致 .get 忽略→法定支出静默蒸发(codex r2)
            raise ValueError(f"Due 含未知科目 {hk}")
        if isinstance(dv, bool) or not isinstance(dv, (int, float)): raise ValueError(f"Due[{hk}] 非数值")
        if not math.isfinite(float(dv)): raise ValueError(f"Due[{hk}] 非有限值(NaN/inf)")
        if dv < 0: raise ValueError(f"Due[{hk}] 为负")
    for sk in (*CASH_KEYS, *CLAIM_KEYS, '官民田', '隐田'):   # CLAIM 也拦(codex r4:负军饷欠→偿还环 rep<0 凭空生钱);非有限同拦
        _sraw = st.get(sk, 0)
        if isinstance(_sraw, bool) or not isinstance(_sraw, (int, float)): raise ValueError(f"开账 stock {sk} 非数值")
        sv = float(_sraw)
        if not math.isfinite(sv): raise ValueError(f"开账 stock {sk} 非有限值(NaN/inf)")
        if sv < 0: raise ValueError(f"开账 stock {sk} 为负")
    Stock_start = cash['省库库银']
    ΣCost = sum(a.get('cost',0) for a in actions if a.get('cost',0) > 0)
    k = 1.0 if (ΣCost == 0 or ΣCost <= Stock_start) else Stock_start/ΣCost
    print(f"⓪ Stock_start={Stock_start:.2f} ΣCost={ΣCost:.2f} k={k:.4f}")
    for a in actions:
        has_cost = a.get('cost',0) > 0
        ec = a.get('cost',0)*k
        amt = a.get('amount',0) * (k if has_cost else 1.0)   # 0-cost action 不缩(spec §6)
        t = a['type']
        if t in ('补饷',):                       # 现金支付补军饷欠(clamp 不超还)
            还 = min(ec, claim['军饷欠']); cash['省库库银'] -= 还; cash_out += 还; r['行政补饷'] += 还
            claim['军饷欠'] -= 还; r['action还']['军饷欠'] += 还
            print(f"  补饷 ec={ec:.2f} 实还={还:.2f}(余{ec-还:.2f}不花)")
        elif t in ('清丈','营建'):                # 行政成本→受款方(吏/工),带 effect
            if ec > 0: cash['省库库银'] -= ec; cash_out += ec; r['行政补饷'] += ec

def _parse_revoke_decree_target(
    db: Any, *,
    target_id: object = "",
    target_kind: object = "",
    target_candidate: object = "",
) -> Optional[Dict[str, Any]]:
    """解析撤回成命目标：仅承诺/旨意（dossier/initiative）；须可走 0056。

    - 纯授权拒（归收权·罢差）
    - issue 仅 active initiative，且 origin_ref 回指可撤案卷（禁 standalone 免代价）
    - dossier 须已颁/执行中
    """
    if str(target_candidate or "").strip() == "含糊":
        return None
    raw = str(target_id or "").strip()
    if not raw:
        return None
    if raw.startswith("authority:"):
        return None  # 纯授权归收权·罢差
    kind = str(target_kind or "").strip()
    if raw.startswith("dossier:"):
        kind = "dossier"
        raw = raw.split(":", 1)[1].strip()
    elif raw.startswith("issue:"):
        kind = "issue"
        raw = raw.split(":", 1)[1].strip()
    if not kind:
        kind = "dossier"
    try:
        tid = int(raw)
    except (TypeError, ValueError):
        return None
    if tid <= 0:
        return None
    if kind == "issue":
        row = db.conn.execute("SELECT * FROM issues WHERE id=?", (tid,)).fetchone()
        if row is None:
            return None
        if str(row["kind"] or "").strip() != "initiative":
            return None
        if str(row["status"] or "").strip() != "active":
            return None
        linked = 0
        origin = str(row["origin_ref"] or "").strip()
        if origin.startswith("dossier:"):
            try:
                linked = int(origin.split(":", 1)[1])
            except (TypeError, ValueError):
                linked = 0
        # standalone / 无合法案卷来源：拒入闸，堵住 cancel_issue 免 0056 旁路
        if linked <= 0:
            return None
        dossier = db.get_decree_dossier(linked)
        if dossier is None or not _dossier_is_revocable_decree(db, dossier):
            return None
        return {
            "target_kind": "issue",
            "target_id": str(tid),
            "issue_id": tid,
            "dossier_id": linked,
        }
    dossier = db.get_decree_dossier(tid)
    if dossier is None or not _dossier_is_revocable_decree(db, dossier):
        return None
    return {
        "target_kind": "dossier",
        "target_id": str(tid),
        "dossier_id": tid,
        "issue_id": 0,
    }

def _apply_authorization_verdict_effect(
    self, state, row, payload, dossier_id,
) -> bool:
    """#528：公开委任案卷顺颁后走 #611 authority_changes 授予槽。

    完整授予条目：动作=授予 + dossier_id + holder_id + privilege + scope。
    不直写 authority_records。
    Returns False when duplicate_active_authority was soft-rejected and
    terminal failure already recorded — caller must return early.
    Returns True when the grant landed.
    """
    from ming_sim.issues import apply_score_extraction

    holder = str(
        payload.get("holder_id")
        or payload.get("assignee_id")
        or payload.get("name")
        or row.get("executor_id")
        or ""
    ).strip()
    privilege = str(payload.get("privilege") or "").strip()
    scope = str(payload.get("scope") or "").strip()
    if not scope:
        t_kind = str(
            payload.get("target_kind") or row.get("target_kind") or ""
        ).strip()
        t_id = str(
            payload.get("target_id") or row.get("target_id") or ""
        ).strip()
        if t_kind and t_id:
            scope = f"{t_kind}:{t_id}"
    if not holder or not privilege or not scope:
        raise ValueError("委任授权案卷缺少 holder_id/privilege/scope")
    out = apply_score_extraction(
        self, state,
        {
            "authority_changes": [{
                "动作": "授予",
                "holder_id": holder,
                "privilege": privilege,
                "scope": scope,
                "dossier_id": int(dossier_id),
            }],
        },
        content=None,
    )
    rows = out.get("authority_changes") or []
    item = rows[0] if rows else {"rejected": True, "reason": "授予未落"}
    if item.get("rejected"):
        reason = str(item.get("reason") or "授予被拒")
        # #1628 / 0150-D5-a：跨案 duplicate 接到 assignment 软通道，不得升格整批。
        if reason == "duplicate_active_authority":
            self.transition_decree_dossier(
                dossier_id, "executing", commit=False,
            )
            self.record_dossier_execution(
                dossier_id, "failed", reason, state.turn,
                close=True, commit=False,
            )
            return False
        raise ValueError(reason)
    return True

