def require_explicit_xiexang_fields(
    *,
    amount: object = 0,
    account: str = "",
    purpose: str = "",
    target_kind: str = "",
    target_id: str = "",
    cadence: str = "",
) -> Dict[str, Any]:
    """#1503 单一权威接缝：严格验形并归一 typed 字段。"""
    from ming_sim.strict_types import strict_int

    facts: list = []

    def _note(field: str, *, current: object, expected: object) -> None:
        facts.append({"field": field, "current": current, "expected": expected})

    try:
        n = strict_int(amount, accept_numeric_strings=False)
    except ValueError:
        n = 0
    if n <= 0:
        _note("amount", current=amount, expected={"type": "positive_int"})
    # #1620：太仓→国库唯一权威 resolve_grant_account；此处不再平行 if。
    canonical_account = resolve_grant_account(grant_action="协饷", account=account)
    if canonical_account not in {"国库", "内库"}:
        _note("account", current=account, expected=["国库", "内库"])
    purpose_cur = str(purpose or "").strip()
    if purpose_cur != "补饷":
        _note("purpose", current=purpose_cur or purpose, expected="补饷")
    canonical_target_kind = str(target_kind or "").strip()
    if canonical_target_kind not in XIEXIANG_TARGET_KINDS:
        _note(
            "target_kind",
            current=canonical_target_kind or target_kind,
            expected=sorted(XIEXIANG_TARGET_KINDS),
        )
    target_id_cur = str(target_id or "").strip()
    if not target_id_cur:
        _note("target_id", current=target_id, expected={"nonempty_str": True})
    cadence_value = str(cadence or "").strip()
    if cadence_value and cadence_value not in {"一次性", "每月"}:
        _note(
            "cadence",
            current=cadence_value,
            expected=["一次性", "每月", ""],
        )
    if facts:
        raise IncompleteXiexangPayloadError(field_failures=facts)
    return {
        "amount": n,
        "account": canonical_account,
        "purpose": "补饷",
        "target_kind": canonical_target_kind,
        "target_id": target_id_cur,
    }

def settle_exposure_from_canonical_actions(db: Any, state: Any, applied: Mapping[str, object]) -> int:
    """只凭 canonical applier 已成功落库的结果消费待办。"""
    consumed = 0
    for todo in db.list_next_audience_todos(status="pending"):
        if todo.get("entry_kind") != ENTRY_KIND:
            continue
        payload = todo.get("payload_json") or {}
        did = int(payload.get("dossier_id") or 0)
        # The same row remains the durable reminder only while the real gap exists.
        if payload.get("decision") == "禁摊派":
            pay_fact = army_pay_fact_for_dossier(db, did) or {}
            if float(pay_fact.get("arrears") or 0) <= 0:
                db.mark_next_audience_todo_status(int(todo["id"]), "consumed", commit=False)
                consumed += 1
            continue
        if payload.get("decision"):
            continue
        origin = f"dossier:{did}"
        dossier = db.get_decree_dossier(did) or {}
        actors = {str(dossier.get("executor_id") or "").strip()}
        for participant in dossier.get("participant_roster") or []:
            if isinstance(participant, Mapping) and participant.get("tier") in {"主办", "协办"}:
                actors.add(str(participant.get("character_id") or "").strip())
        actors.discard("")
        successful = lambda x: isinstance(x, Mapping) and not x.get("rejected")
        # Identity is the successfully promulgated case-bound dossier, never an
        # unrelated fiscal receipt with a convenient shape.
        pay_fact = army_pay_fact_for_dossier(db, did) or {}
        prohibition = active_prohibition_dossier(db, did)
        stopped = prohibition is not None
        if prohibition is not None:
            # The canonical prohibition owns the durable, idempotent rollback receipt.
            from ming_sim.issues import neutralize_covert_fiscal_effects
            neutralize_covert_fiscal_effects(
                db, state, exposed_dossier_id=did,
                prohibition_dossier_id=int(prohibition["id"]),
            )
        levy_transfer = any(
            is_actual_population_transfer(x)
            and x.get("origin_ref") == origin and x.get("reason") == "摊派"
            for x in applied.get("population_transfers") or []
        )
        covert_effect = any(
            successful(x) and x.get("applied") is True
            and x.get("origin_ref") == origin and x.get("beyond_intent") is True
            for key in ("economy_moves", "fiscal_changes", "fiscal_creates", "fiscal_removes")
            for x in applied.get(key) or []
        )
        person_changes = list(applied.get("applied_person_changes") or [])
        person_changes += list((applied.get("issue_summary") or {}).get("applied_person_changes") or [])
        punished = any(
            successful(x) and x.get("动作") in {"处置", "罢黜"}
            and str(x.get("name") or "") in actors for x in person_changes
        )
        paid_cost = any(
            successful(x)
            and str(x.get("origin") or "").startswith(f"{origin}:relation:")
            and ({str(x.get("source") or ""), str(x.get("target") or "")} & actors)
            for x in applied.get("relation_edge_event_resolutions") or []
        )
        decisions = [
            name for name, matched in (
                ("禁摊派", stopped), ("默许", levy_transfer and covert_effect),
                ("查办", punished and paid_cost),
            ) if matched
        ]
        if len(decisions) != 1:
            continue
        decision = decisions[0]
        # 禁令的真实后果是欠饷缺口继续顶在御前，故保留同一 pending 行而非造第二 dispatcher。
        reopened = (
            decision == "禁摊派" and float(pay_fact.get("arrears") or 0) > 0
        )
        status = "pending" if reopened else "consumed"
        db.mark_next_audience_todo_status(
            int(todo["id"]), status,
            payload_patch={"decision": decision, "decided_turn": int(state.turn),
                           "shortfall_reopened": reopened}, commit=False,
        )
        consumed += 1
    return consumed

def _is_cover_change(item: Dict[str, object]) -> bool:
    """包庇：非惩处性、仍挂变形案卷 origin 的人事动作（留任/开释口径）。"""
    if _is_punitive_change(item):
        return False
    action = str(item.get("动作") or item.get("action") or "").strip()
    if action in {"任命", "调任"}:
        return True
    if action == "处置":
        status = str(item.get("status") or "").strip()
        return status in {"active"} or not status
    return False

def get_rescript_desk_rows_by_keys(
    self, keys: Sequence[str],
) -> List[Dict[str, object]]:
    """按 decision_key 取 desk 行（含 decided）——C1.1 崩溃重入 already_applied 用。"""
    out: List[Dict[str, object]] = []
    seen: set[str] = set()
    for raw in keys:
        key = str(raw or "").strip()
        if not key or key in seen:
            continue
        parts = key.split(":")
        if len(parts) != 3:
            continue
        kind, turn_s, idx_s = parts
        try:
            turn_i, idx_i = int(turn_s), int(idx_s)
        except (TypeError, ValueError):
            continue
        if kind not in {"rescript_draft", "decision"}:
            continue
        r = self.conn.execute(
            """
            SELECT *
            FROM pending_decisions
            WHERE turn = ? AND idx = ? AND kind = ?
            """,
            (turn_i, idx_i, kind),
        ).fetchone()
        if r is None:
            continue
        seen.add(key)
        out.append(self._project_rescript_desk_row(r))
    return out

def _dispatch_promises(
    db: Any, state: Any, raw: object, *, night_id: int,
    chat_turn_id: int, source: Provenance,
    preexisting_pending_ids: set[int],
) -> SectionResult:
    from ming_sim.strict_types import strict_int

    items, rejected = _section_items(raw, label="应允/拒绝/修改声明", source=source)
    applied: List[Any] = []
    for item in items:
        try:
            # Strict positive int only — bool/float/numeric strings must not
            # coerce via bare int() into another night's pending id.
            action_id = strict_int(
                item.get("action_id"), accept_numeric_strings=False,
            )
        except (TypeError, ValueError):
            action_id = 0
        decision = str(item.get("decision") or "").strip()
        if action_id <= 0 or decision not in {"应允", "拒绝", "修改", "留中"}:
            _reject(
                rejected, item, "判词声明须含正 action_id 与 应允/拒绝/修改/留中",
                "invalid_shape", source,
            )
            continue
        # 只认本夜（或本次无夜上下文）暂存清单里的动作：id 真实存在但挂在
        # 另一夜，声明也不得应允/拒绝它——同样按「不存在实体」拒收（不静默
        # 误批，也不当真拒收物理删除他夜暂存）。
        row = db.conn.execute(
            "SELECT night_id, kind, action, minister_name, night_approved, payload_json FROM pending_actions "
            "WHERE id=? AND turn=? AND status='pending'",
            (action_id, int(state.turn)),
        ).fetchone()
        if (
            row is None or action_id not in preexisting_pending_ids
            or int(row["night_id"] or 0) != int(night_id)
        ):
            _reject(
                rejected, item, f"暂存动作不属本夜暂存清单：{action_id}",
                "missing_ref", source,
            )
            continue
        kind = str(row["kind"] or "")
        action = str(row["action"] or "")
        declared_mode = item.get("mode")
        if declared_mode is not None and (
            kind != "directive" or decision != "应允"
            or not isinstance(declared_mode, str)
            or declared_mode not in {"ordinary", "midzhi"}
        ):
            _reject(rejected, item, "应允模式仅可指定普通/中旨拟旨", "invalid_shape", source)
            continue
        applied_row: Dict[str, Any] = {
            "action_id": action_id, "decision": decision, "kind": kind, "action": action,
        }
        if decision == "留中":
            if kind != "directive":
                _reject(rejected, item, "仅拟旨候选可留中", "invalid_shape", source)
                continue
            db.hold_over_pending_actions(
                int(state.turn), str(row["minister_name"]), [action_id],
            )
        elif decision == "修改":
            new_content = item.get("new_content")
            if (
                kind != "secret_order" or action != "新建"
                or not isinstance(new_content, str) or not new_content.strip()
            ):
                _reject(rejected, item, "只有新建密令可用非空 typed new_content 修改", "invalid_shape", source)
                continue
            payload = json.loads(row["payload_json"] or "{}")
            if not isinstance(payload, dict):
                raise ValueError("密令候选载荷损坏")
            payload["content"] = new_content
            db.conn.execute(
                "UPDATE pending_actions SET payload_json=?, night_approved=0 WHERE id=?",
                (json.dumps(payload, ensure_ascii=False), action_id),
            )
        elif decision == "应允":
            # ADR 0038：密令应允即落地（夜内直写白名单）；任免/拟旨只标
            # night_approved，收夜才提交。

def _strategic_event_result_preflight_error(
    db: GameDB,
    state: GameState,
    event_id: str,
    event_title: str,
    outcome_label: str,
    region_deltas: Dict[str, object],
    army_deltas: Dict[str, object],
    power_updates: Dict[str, object],
    person_changes: List[Dict[str, object]],
    new_armies: List[object],
    content: Optional[GameContent],
    llm_config: Any,
    preflight_event: Event,
    ordered_region_items: Optional[list[tuple[str, object]]] = None,
    ordered_army_items: Optional[list[tuple[str, object]]] = None,
    ordered_power_items: Optional[list[tuple[str, object]]] = None,
) -> str:
    """ADR0014：战略事件战果是同一信封，落库前先拦整组可预见拒收项。

    归属已由转译 event_id 声明；本函数只验信封内容，不再从 reason 推断。
    """
    legacy_mods = db.legacy_modifiers(state)
    region_valid_fields = set(REGION_SCORE_FIELDS + REGION_QUANTITY_FIELDS + REGION_TEXT_FIELDS + FISCAL_SCORE_FIELDS)
    region_valid_fields.add("cannon")
    region_numeric_fields = set(REGION_SCORE_FIELDS + REGION_QUANTITY_FIELDS + FISCAL_SCORE_FIELDS)
    region_numeric_fields.add("cannon")
    army_valid_fields = set(ARMY_SCORE_FIELDS + ARMY_QUANTITY_FIELDS + ARMY_TEXT_FIELDS)
    army_numeric_fields = set(ARMY_SCORE_FIELDS + ARMY_QUANTITY_FIELDS)

    def _int_delta_error(kind: str, target_id: str, raw_field: object, value: object) -> str:
        if isinstance(value, bool) or isinstance(value, float):
            return f"战略/外敌事件「{event_title or event_id}」战果 {kind}.{target_id}.{raw_field} 值非整数：{value!r}"
        try:
            int(value)
        except (TypeError, ValueError):
            return f"战略/外敌事件「{event_title or event_id}」战果 {kind}.{target_id}.{raw_field} 值非整数：{value!r}"
        return ""

    def _noop_error(kind: str, target_id: str, raw_field: object, value: object) -> str:
        return (
            f"战略/外敌事件「{event_title or event_id}」战果 {kind}.{target_id}.{raw_field} "
            f"无真实世界状态变化：{value!r}"
        )

    def _region_noop_error(region_id: str, row: sqlite3.Row, raw_field: object, value: object) -> str:
        field = REGION_FIELD_ALIASES.get(str(raw_field).strip(), str(raw_field).strip())
        if field == "reason":
            return ""
        if field == "cannon":
            delta = int(value)
            cap = int(row["city_level"]) * 8
            old_value = int(row["cannon"])
            if max(0, min(cap, old_value + delta)) == old_value:
                return _noop_error("region", region_id, raw_field, value)
            return ""
        if field in FISCAL_SCORE_FIELDS:
            fiscal = json.loads(str(row["fiscal"] or "{}"))
            old_value = int(fiscal.get(field, 50))
            delta = int(value)
            net_pct = int(((legacy_mods.get("regions") or {})
                           .get(region_id) or {}).get(field, 0) or 0)
            if net_pct:
                delta = db.apply_legacy_pct(delta, net_pct)
            if max(0, min(100, old_value + delta)) == old_value:
                return _noop_error("region", region_id, raw_field, value)
            return ""
        if field in REGION_SCORE_FIELDS:
            old_value = int(row[field])
            delta = int(value)
            net_pct = int(((legacy_mods.get("regions") or {})
                           .get(region_id) or {}).get(field, 0) or 0)
            if net_pct:
                delta = db.apply_legacy_pct(delta, net_pct)
            if max(0, min(100, old_value + delta)) == old_value:
                return _noop_error("region", region_id, raw_field, value)
            return ""
        if field in REGION_QUANTITY_FIELDS:
            old_value = int(row[field])
            if max(0, old_value + int(value)) == old_value:
                return _noop_error("region", region_id, raw_field, value)

def office_leverage_multiplier(office: object, already_normalized: bool = False) -> float:
    """Map an office title to the faction-leverage rank multiplier via offices.json.

    Comma-separated concurrent titles take the highest recognized multiplier. Titles with
    no leverage-bearing stem keep the historical conservative default 1.0.
    """
    del already_normalized  # retained for the historical caller contract
    parts = concurrent_office_titles(office)
    if not parts:
        return DEFAULT_LEVERAGE_MULTIPLIER

    table = _table()
    office_weights: list[float] = []
    for part in parts:
        matches: list[tuple[int, float]] = []
        modifiers: list[float] = []
        for rule in _iter_rank_rules(table):
            if "leverage_multiplier" not in rule:
                continue
            for stem in rule.get("stems") or []:
                token = str(stem or "").strip()
                if not token or token not in part:
                    continue
                weight = float(rule["leverage_multiplier"])
                if token in {"候补", "候用"}:
                    modifiers.append(weight)
                else:
                    matches.append((len(token), weight))
        if matches or modifiers:
            longest = max((length for length, _weight in matches), default=-1)
            base_weights = [weight for length, weight in matches if length == longest]
            # Longest title stem identifies the office; explicit status modifiers then
            # constrain it. This preserves old min-within-title semantics without letting
            # generic substrings (御史 inside 佥都御史) demote the base title.
            office_weights.append(min([*base_weights, *modifiers]))
    # Concurrent offices contribute at the strongest real office, as before.
    return max(office_weights, default=DEFAULT_LEVERAGE_MULTIPLIER)

def apply_appointment(
    db: GameDB,
    state: GameState,
    content: GameContent,
    data: Optional[Dict[str, object]] = None,
    llm_config: Optional[LLMConfig] = None,
    commit: bool = True,
) -> Tuple[str, str]:
    """诏书任命共用落地：建档入库，本回合即可召见。"""
    if not data:
        return ("", "")
    if "approved" in data and not bool(data.get("approved")):
        return ("", "")
    name = str(data.get("name") or "").strip()
    office = str(data.get("office") or "").strip()
    if not name or not office:
        return ("", "")
    office = normalize_office(office)
    # 显式名分（office_type ∈ PERSON_TITLE_KINDS）在此建 Character 前就得保住：add_character 的
    # 名分守卫看的是 character.office_type，若这里先被 infer 反推成官职（office='诸生'→'生员'），
    # 守卫永远见不到名分、误建 offices/character_offices（#1059 codex l6h）。
    office_type = resolve_office_type_preserving_title(
        office,
        str(data.get("office_type") or "").strip(),
        "待铨",
        llm_config or db.llm_config,
    )
    if office_type == "后宫":
        return ("", "")

    # ── 查重：精确名 + aliases 命中即拒，不重复建档 ──────────
    # 身份归一认识未仕/宗藩——在册者（含史可法诸生）由此拒新建，走 apply_office_appointment。
    if name in content.characters:
        return ("", "")
    existing = _find_existing_minister(content, name, db)
    if existing is not None:
        return ("", "")

    # ── 职位替换：腾缺现任者 → dismissed ───────────────────────────
    displaced = ""
    replaces = str(data.get("replaces") or "").strip()
    if replaces and replaces in content.characters:
        old = content.characters[replaces]
        if old.status == "active":
            db.set_character_status(
                state, replaces, "dismissed",
                reason=f"{office}改授{name}，原任去职",
                content=content,
                commit=commit,
            )
            displaced = replaces

    person_fields = canonical_new_appointment_person_fields(
        content, data.get("faction"),
    )
    character = Character(
        name=name,
        office=office,
        office_type=office_type,
        aliases=[],
        personal_skills=[],
        power_id="ming",
        status="active",
        office_region=str(
            data.get("office_region") or data.get("region_id") or ""
        ).strip(),
        **person_fields,
    )
    content.characters[name] = character
    db.add_character(state, character, llm_config=llm_config, commit=commit)
    # add_character 已写入并分配 portrait_id，回写到内存对象
    row = db.conn.execute(
        "SELECT portrait_id FROM characters WHERE name=?", (name,)
    ).fetchone()
    if row:
        character.portrait_id = str(row["portrait_id"])
    return (name, displaced)

def validate_affected_parties(
    affected: object, *, faction_names: object, class_names: object,
) -> None:
    """Validate typed signed reactions; extra explanatory keys remain allowed."""
    if not isinstance(affected, list) or not all(
        isinstance(item, dict)
        and {"kind", "key", "direction", "intensity"}.issubset(item)
        and item.get("kind") in {"faction", "class"}
        and isinstance(item.get("key"), str)
        and item["key"] in (faction_names if item.get("kind") == "faction" else class_names)
        and item.get("direction") in {"positive", "negative"}
        and item.get("intensity") in {"weak", "strong"}
        for item in affected
    ):
        raise ValueError("affected_parties 须为在册 typed signed 反应清单")

def validate_verdict_affected_parties(
    verdict: object, mode: str, *, faction_names: object, class_names: object,
) -> None:
    """Enforce the mode/decision reaction shape at every public verdict seam.

    #657 §C.8 later-wins：mode=midzhi 不猜/不强制 affected_parties（顺颁与打回皆然）；
    ordinary 打回仍须非空 typed 清单；ordinary 顺颁必须省略。
    """
    if not isinstance(verdict, dict):
        raise ValueError("案卷 verdict 须为对象")
    decision = verdict.get("decision")
    present = "affected_parties" in verdict
    if mode == "midzhi":
        # 中旨接缝不消费该字段；若 LLM 夹带则仅校验形状（下游剥离/不落库）。
        if present and verdict.get("affected_parties") not in (None, []):
            validate_affected_parties(
                verdict.get("affected_parties"),
                faction_names=faction_names, class_names=class_names,
            )
        return
    required = decision == "rejected"
    if required and (not present or not verdict.get("affected_parties")):
        raise ValueError("打回判决的 affected_parties 必须为非空 typed 清单")
    if not required and present:
        raise ValueError("普通顺颁判决必须省略 affected_parties")
    validate_affected_parties(
        verdict.get("affected_parties", []),
        faction_names=faction_names, class_names=class_names,
    )

def _choose_rescripts(
    db: GameDB, turn: int, hostile: int, vital: int, appointment: int,
) -> list[dict]:
    """Persist choices exactly as the normal session boundary does, then phase2 owns them."""
    chosen = []
    for decision in db.list_pending_decisions(turn):
        options = decision["options"]
        if decision["event_id"] == f"dossier:{hostile}":
            choice = next(row for row in options if row.get("dossier_decision") == "hold")
        elif decision["event_id"] in {f"dossier:{vital}", f"dossier:{appointment}"}:
            choice = next(row for row in options if row.get("dossier_decision") == "withdrawn")
        else:
            # authority_edge and any other reject: explicit non-force via dossier_decision.
            # Never fall through to options[0] (force_promulgated on ordinary rejects).
            choice = next(
                row for row in options
                if row.get("dossier_decision") in {"withdrawn", "hold"}
            )
        db.conn.execute(
            "UPDATE pending_decisions SET choice_json=?,status='chosen' WHERE turn=? AND idx=?",
            (json.dumps(choice, ensure_ascii=False), int(turn), int(decision["idx"])),
        )
        chosen.append({"event_id": decision["event_id"], "choice": choice})
    db.conn.commit()
    return chosen

