def gate_key_form_error(key: str) -> str:
    """trigger_gate key 形态校验（#12 Q3 fail-loud，ADR 0012 残留 4b①）。合法→""；非法→错误说明。
    bare key（无 "."）须是已知 metric；点分 key 首段须是合法表名、结构完整（去末段聚合后 ≥3 段）。
    字段名(列)是否存在由 _eval_gate_key 运行期对 DB schema 兜底（content load 无 DB 不校验列）。"""
    if "." not in key:
        if key not in GATE_METRIC_KEYS:
            return f"未知 metric「{key}」（须 {'/'.join(GATE_METRIC_KEYS)} 之一，或用 表.id.字段 形式）"
        return ""
    parts = key.split(".")
    if parts[0] not in GATE_TABLES:
        return f"未知表「{parts[0]}」（须 {'/'.join(GATE_TABLES)} 之一）"
    if parts[-1] in GATE_AGG_FUNCS:
        parts = parts[:-1]
    if len(parts) < 3:
        return "结构不完整（应形如 表.id.字段[.聚合]）"
    # 拒空段（cmr r1 codex）：空 id / 空字段 / | 列表含空成员 → 静默不达标或 SQL 崩，须 fail-loud
    field = parts[-1]
    id_segment = ".".join(parts[1:-1])
    if not field.strip() or not id_segment.strip():
        return "id 或 字段 为空"
    if any(not m.strip() for m in id_segment.split("|")):
        return "id 列表含空成员（| 分隔）"
    # class.<名>[@<region>] 成员校验（cmr r2/online concur）：类名（@ 前）非空；带 @ 者 region
    # （@ 后）也须非空——空 region 的 @ 是「想写 regional 却漏 region」的 malformed regional gate，
    # runtime 会静默回退 national class 行（应 fail-loud；online codex P2）。national 用无 @ 形式。
    if parts[0] == "class":
        for member in id_segment.split("|"):
            if not member.split("@", 1)[0].strip():
                return "class 名为空（@ 前）"
            if "@" in member and not member.split("@", 1)[1].strip():
                return "class @ 后 region 为空（regional gate 须指定 region；national 用无 @ 形式）"
    if parts[0] == "event" and field != "triggered":
        return "event 数值 gate 仅支持 triggered 字段（形如 event.<event_id>.triggered）；文本 gate 用 terminal_state/terminal_reason"
    return ""

def stopped_covert_effect(
    db: Any, *, origin_ref: object, beyond_intent: object = False,
) -> bool:
    """True only for a post-prohibition covert leg owned by the targeted old dossier."""
    origin = str(origin_ref or "").strip()
    if not origin.startswith("dossier:"):
        return False
    raw_id = origin.removeprefix("dossier:")
    if not raw_id.isdigit():
        return False
    from ming_sim.simulation import read_beyond_intent_raw
    beyond = db.coerce_beyond_intent_flag(read_beyond_intent_raw({"beyond_intent": beyond_intent}))
    if not beyond:
        return False
    return active_prohibition_dossier(db, int(raw_id)) is not None

def effect_origin_rejection(self, origin_ref: str) -> Dict[str, object] | None:
    """Authorize extractor provenance immediately before a durable write.

    When apply_score_extraction arms ``_batch_authorized_open_affair_ids``,
    ``affair:<id>`` must also sit in that frozen batch set — one authority
    for every durable-effect carrier (fiscal included).
    """
    value = str(origin_ref or "").strip()
    valid = value == "盘面自发"
    unauthorized_batch = False
    if value.startswith("dossier:"):
        try:
            dossier_id = int(value.split(":", 1)[1])
            valid = dossier_id > 0 and self.get_decree_dossier(dossier_id) is not None \
                and self.dossier_authorizes_effects(dossier_id)
        except (OverflowError, TypeError, ValueError):
            valid = False
    elif value.startswith("affair:"):
        try:
            from ming_sim.entities.affair.store import (
                UnauthorizedAffairOriginRef,
                parse_origin_ref,
            )
            kind, affair_id = parse_origin_ref(value)
            if kind == "affair" and affair_id is not None:
                self.affairs.get(int(affair_id))
                authorized = getattr(self, "_batch_authorized_open_affair_ids", None)
                if authorized is not None and affair_id not in authorized:
                    valid = False
                    unauthorized_batch = True
                else:
                    valid = True
            else:
                valid = False
        except (KeyError, OverflowError, TypeError, ValueError):
            valid = False
    if valid:
        return None
    if unauthorized_batch:
        from ming_sim.entities.affair.store import UnauthorizedAffairOriginRef
        return {
            "rejected": True,
            # Distinct from missing/invalid existence — strategic preflight
            # must not envelope-fail this; apply paths still reject itemwise.
            "category": "unauthorized_affair_origin",
            "reason": str(UnauthorizedAffairOriginRef()),
        }
    return {
        "rejected": True,
        "category": "missing_origin_ref" if not value else "invalid_origin_ref",
        "reason": ("效果缺 origin_ref；盘面自然演化须显式标为「盘面自发」"
                   if not value else f"origin_ref 非法：{value}"),
    }

def _promulgation_decision_raw(row: dict) -> str:
    """Resolve the current promulgation-slot raw enum for a dossier row."""
    verdict = str(row.get("settlement_verdict") or "").strip()
    if verdict in DOSSIER_DECISION_CN:
        return verdict
    decision = str(row.get("promulgation_decision") or "").strip()
    if decision in DOSSIER_DECISION_CN:
        return decision
    if bool(row.get("was_force_promulgated")):
        return "force_promulgated"
    stigma = row.get("stigma") or []
    if isinstance(stigma, list):
        for item in stigma:
            if not isinstance(item, dict) or item.get("kind") != "midzhi":
                continue
            source = str(item.get("source_action") or "").strip()
            if source == "force_promulgated":
                return "force_promulgated"
            if source == "promulgated":
                return "promulgated"
            if source == "rejected":
                return "rejected"
    return decision

def _apply_authority_change_item(
    db: GameDB, state: GameState, item: Dict[str, object],
) -> Dict[str, object]:
    """Apply one production-slot authority grant/revoke under the #611 contract."""
    if "dossier_id" not in item or item.get("dossier_id") in (None, ""):
        raise ValueError("missing_dossier_source")
    try:
        dossier_id = _parse_sqlite_id(item.get("dossier_id"))
    except (TypeError, ValueError):
        raise ValueError("missing_dossier_source") from None
    if dossier_id <= 0 or db.get_decree_dossier(dossier_id) is None:
        raise ValueError("missing_dossier_source")
    if not db.dossier_authorizes_effects(dossier_id):
        raise ValueError("dossier_not_effect_eligible")
    op = str(item.get("动作") or item.get("op") or "").strip()
    if op not in _AUTHORITY_GRANT_OPS | _AUTHORITY_REVOKE_OPS:
        raise ValueError("授权变更动作只收授予/收回")

    if op in _AUTHORITY_GRANT_OPS:
        holder_id = str(item.get("holder_id") or "").strip()
        privilege = str(item.get("privilege") or item.get("权项") or "").strip()
        scope = str(item.get("scope") or item.get("事域") or "").strip()
        if not holder_id or not privilege or not scope:
            raise ValueError("授予项必须含 holder_id/privilege/scope")
        if privilege not in AUTHORITY_PRIVILEGE_SET:
            raise ValueError("授权权项不在首批枚举")
        kind, separator, target_id = scope.partition(":")
        if not separator or not kind or not target_id:
            raise ValueError("invalid_authority_scope")
        if not db.conn.execute(
            "SELECT 1 FROM characters WHERE name=?", (holder_id,)
        ).fetchone():
            raise ValueError("授权对象不在人物档")
        origin = db.find_authority_by_origin(
            dossier_id, holder_id=holder_id, privilege=privilege, scope=scope,
        )
        if origin is not None:
            # Origin idempotency is independent of current applicability: a
            # revoked or expired grant remains the same durable authority row.
            return {
                "动作": "授予",
                "authority_id": int(origin["id"]),
                "dossier_id": dossier_id,
                "holder_id": holder_id,
                "privilege": privilege,
                "scope": scope,
                "reason": "same_dossier_replay",
            }
        effective_raw = item.get("effective_turn", item.get("生效回合"))
        expires_raw = item.get("expires_turn", item.get("失效回合"))
        effective_turn = (
            int(state.turn) if effective_raw in (None, "")
            else _parse_sqlite_id(effective_raw)
        )
        expires_turn = (
            None if expires_raw in (None, "")
            else _parse_sqlite_id(expires_raw)
        )
        if expires_turn is not None and expires_turn < effective_turn:
            raise ValueError("授权失效回合不得早于生效回合")
        existing = db.find_active_authority(
            state.turn, holder_id=holder_id, privilege=privilege, scope=scope,
        )
        if existing is not None:
            raise ValueError("duplicate_active_authority")
        cursor = db.conn.execute(
            "INSERT INTO authority_records "
            "(holder_id,privilege,scope,effective_turn,expires_turn,dossier_id) "
            "VALUES (?,?,?,?,?,?)",
            (
                holder_id, privilege, scope, effective_turn, expires_turn,
                dossier_id,
            ),
        )
        authority_id = int(cursor.lastrowid)
        return {
            "动作": "授予",
            "authority_id": authority_id,
            "dossier_id": dossier_id,
            "holder_id": holder_id,
            "privilege": privilege,

def _pending_person_changes_block_event_gate(
    ev: Event,
    pending_person_changes: List[Dict[str, object]],
    db: GameDB,
    *,
    allow_legacy_partial_power: bool = False,
    content: Optional[GameContent] = None,
    shadow_rows: Optional[Dict[str, Dict[str, str]]] = None,
    power_shadow_rows: Optional[Dict[str, Dict[str, int]]] = None,
    valid_regions: Optional[set[str]] = None,
) -> bool:
    """Re-check character status gates against accepted same-turn person changes.

    Status-changing person writes intentionally remain post-issue to preserve settlement
    ordering, but event_pool must not ignore a same-turn removal of an event actor.
    """
    if not pending_person_changes or not ev.trigger_gate:
        return False
    pending_fields: Dict[str, Dict[str, str]] = {}
    pending_power_fields: Dict[str, Dict[str, int]] = {}
    shadow_rows = (
        _load_pending_gate_shadow_rows(db)
        if shadow_rows is None
        else {name: dict(row) for name, row in shadow_rows.items()}
    )
    power_shadow_rows = (
        _load_pending_gate_power_shadow_rows(db)
        if power_shadow_rows is None
        else {power_id: dict(row) for power_id, row in power_shadow_rows.items()}
    )
    valid_regions = _load_pending_gate_valid_regions(db) if valid_regions is None else set(valid_regions)

    def row_value(row: Dict[str, str], field: str, default: str = "") -> str:
        return str(row.get(field) or default)

    def character_row(name: str) -> Optional[Dict[str, str]]:
        return shadow_rows.get(name)

    def overlay(name: str, field: str, value: object) -> None:
        value_text = str(value or "").strip()
        pending_fields.setdefault(name, {})[field] = value_text
        if name in shadow_rows:
            shadow_rows[name][field] = value_text

    def power_row(power_id: str) -> Optional[Dict[str, int]]:
        return power_shadow_rows.get(power_id)

    def overlay_power_delta(power_id: object, raw_changes: object) -> None:
        pid = str(power_id or "").strip()
        if not pid or not isinstance(raw_changes, dict):
            return
        row = power_row(pid)
        if row is None:
            return
        for raw_field, value in raw_changes.items():
            field = POWER_FIELD_ALIASES.get(str(raw_field).strip(), str(raw_field).strip())
            if field in {"reason", "last_action"}:
                continue
            if field not in _PENDING_POWER_GATE_FIELDS:
                continue
            try:
                if isinstance(value, bool) or isinstance(value, float):
                    raise ValueError("非整数 delta")
                delta = int(value)
            except (TypeError, ValueError):
                continue
            old_value = int(row[field])
            new_value = max(0, min(100, old_value + delta))
            if new_value == old_value:
                continue
            row[field] = new_value
            pending_power_fields.setdefault(pid, {})[field] = new_value

    def pending_power_gate_value(key: str) -> Optional[int]:
        parts = key.split(".")
        if not parts or parts[0] != "power":
            return None
        agg = None
        if parts[-1] in _GATE_AGG_FUNCS:
            agg = parts[-1]
            parts = parts[:-1]

def _consume_rescript_answers(
    session: Any, chain: Dict[str, Any], *, source: Provenance,
) -> None:
    """把已裁批红接回案卷 / 请旨续推；幂等，已落不动。

    同一旨 / 同一世界段多问须全部答完才续推一次（ADR 0157 步骤 4）。
    """
    db, state = session.db, session.state
    turn = int(state.turn)
    from ming_sim.rescript_draft import consume_memorial_answers
    consume_memorial_answers(session, chain, source=source)
    rows = db.list_pending_decisions(turn)
    decided = [r for r in rows if str(r.get("status") or "") == "decided"]
    if not decided:
        return

    def _answer_from_row(row: Dict[str, object]) -> Dict[str, object]:
        choice = row.get("choice") if isinstance(row.get("choice"), dict) else {}
        return {
            **row, "choice": dict(choice),
            "label": str(choice.get("label") or ""),
            "hint": str(choice.get("hint") or ""),
            "note": str(choice.get("note") or ""),
            "context": str(row.get("context") or ""),
            "event_id": str(row.get("event_id") or ""),
            "title": str(row.get("title") or ""),
        }

    for row in decided:
        event_id = str(row.get("event_id") or "")
        if event_id.startswith("deliberation:"):
            from ming_sim.rescript_actions import apply_imperial_deliberation_push
            original = db.get_decree_dossier(int(event_id.partition(":")[2]))
            if (row["choice"] or {}).get("action") == "imperial_push" and (original["payload"] or {}).get("deliberation_state") == "stalled":
                with atomic(db):
                    apply_imperial_deliberation_push(
                        db, state, target_dossier_id=int(original["id"]),
                        decision_key=row["decision_key"],
                        decree_text=(row.get("choice") or {}).get("note", ""),
                    )
            continue
        if not event_id.startswith("dossier:"):
            continue
        choice = row.get("choice") if isinstance(row.get("choice"), dict) else {}
        _apply_decided_triad(db, state, row, choice, content=session.content)

    world_rows = [
        r for r in rows
        if str(r.get("event_id") or "").startswith(_WORLD_QUESTION_PREFIX)
        and int(str(r["event_id"]).rsplit(":", 1)[1]) >= int(chain.get("world_question_offset", 0))
    ]
    if (
        world_rows
        and all(str(r.get("status") or "") == "decided" for r in world_rows)
        and chain.get("world_questions")
    ):
        _record_world_question_event_choices(db, state, chain, world_rows, turn=turn)
        continue_world_after_answers(
            session, chain,
            answers=[_answer_from_row(r) for r in sorted(world_rows, key=lambda r: r["answer_order"])],
            source=source,
        )

    decree_rows_by_ref: Dict[str, List[Dict[str, object]]] = {}
    for row in rows:
        event_id = str(row.get("event_id") or "")
        if not event_id.startswith(_DECREE_QUESTION_PREFIX):
            continue
        body = event_id[len(_DECREE_QUESTION_PREFIX):]
        ref, _, idx = body.rpartition(":")
        if int(idx) < int((chain.get("decree_question_offsets") or {}).get(ref, 0)):
            continue
        decree_rows_by_ref.setdefault(ref, []).append(row)
    for ref, ref_rows in decree_rows_by_ref.items():
        if not all(str(r.get("status") or "") == "decided" for r in ref_rows):
            continue
        continue_decree_after_answers(
            session, decree_ref=ref, chain=chain,
            answers=[_answer_from_row(r) for r in sorted(ref_rows, key=lambda r: r["answer_order"])],
            source=source,
        )

def _write_locations_in_source(source: str, relative: str) -> set[str]:
    """Scan one module's source for direct ``characters``-mutating execute() SQL.

    Handles both plain string literals AND f-strings (``ast.JoinedStr``): an
    f-string execute arg like ``f"DELETE FROM characters WHERE ..."`` is the
    Call arg as a whole, so it matches directly (its inner ``Constant`` parts
    have the JoinedStr as parent — not the Call — so they are correctly skipped
    by ``_is_sql_execute_argument``; before this an f-string-only write point
    escaped the inventory scan entirely)."""
    tree = ast.parse(source)
    parents: dict[ast.AST, ast.AST] = {}
    for parent in ast.walk(tree):
        for child in ast.iter_child_nodes(parent):
            parents[child] = parent
    found: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            sql_src = node.value
        elif isinstance(node, ast.JoinedStr):
            sql_src = "".join(
                v.value for v in node.values
                if isinstance(v, ast.Constant) and isinstance(v.value, str)
            )
        else:
            continue
        if not _is_sql_execute_argument(node, parents):
            continue
        sql = " ".join(sql_src.split())
        if not any(marker in sql for marker in _MUTATING_SQL_MARKERS):
            continue
        function_name = _enclosing_function_name(node, parents)
        found.add(_inventory_location(relative, function_name, sql))
    return found

def persist_answers(db: Any, state: Any, choices: list, *, content: Any = None) -> None:
    """Validate the entire envelope before writing. Same-body retries are idempotent."""
    requests = [canonical_choice(raw) for raw in choices]
    keys = [item["decision_key"] for item in requests]
    if len(set(keys)) != len(keys):
        raise ValueError("重复 decision_key")
    rows = {r["decision_key"]: r for r in db.get_rescript_desk_rows_by_keys(keys)}
    open_keys = {r["decision_key"] for r in db.list_rescript_desk(int(state.turn))}
    for choice in requests:
        row = rows.get(choice["decision_key"])
        if row is None:
            raise ValueError("decision_key 不在案头")
        if row["choice"]:
            if row["choice"] != choice:
                raise ValueError("已落批语不可改写")
            continue
        if choice["decision_key"] not in open_keys:
            raise ValueError("原案当前不可批")
        event_id = str(row.get("event_id") or "")
        action = choice.get("dossier_decision") or choice.get("action") or ""
        if event_id.startswith("dossier:"):
            legal = {o.get("dossier_decision") for o in row["options"]}
            if action not in legal:
                raise ValueError("打回旨须显式选择合法强颁、收回或留中")
        elif event_id.startswith("deliberation:"):
            if action not in {o.get("action") for o in row["options"]}:
                raise ValueError("无人站台案须显式选择御笔强推或留存")
        else:
            if action not in ({"", "midzhi"} if row["kind"] == "rescript_draft" else {""}):
                raise ValueError("批语不使用旧六动作；另旨·中旨只接急务原案")
            if not (choice.get("label", "").strip() or choice.get("note", "").strip()):
                raise ValueError("批语为空")
            if choice.get("label") and choice["label"] not in {o.get("label") for o in row["options"]}:
                raise ValueError("所选票拟不在原奏折中")
    with atomic_and_reload(db, state, content=content):
        order = int(db.conn.execute(
            "SELECT COALESCE(MAX(answer_order),0) FROM pending_decisions WHERE answered_turn=?", (int(state.turn),),
        ).fetchone()[0])
        for choice in requests:
            row = rows[choice["decision_key"]]
            if row["choice"]:
                continue
            order += 1
            db.conn.execute(
                "UPDATE pending_decisions SET choice_json=?, status='decided', answered_turn=?, answer_order=? "
                "WHERE turn=? AND idx=? AND kind=? AND status='pending'",
                (json.dumps(choice, ensure_ascii=False), int(state.turn), order,
                 row["source_turn"], row["idx"], row["kind"]),
            )
            event_id = str(row.get("event_id") or "")
            from ming_sim.month_chain import _DECREE_QUESTION_PREFIX, _WORLD_QUESTION_PREFIX
            if row["kind"] == "decision" and event_id and not event_id.startswith(
                ("dossier:", "deliberation:", _DECREE_QUESTION_PREFIX, _WORLD_QUESTION_PREFIX)
            ):
                db.record_event_decision_choice(state, event_id, choice, commit=False)

