def _payloads_match(durable_row: Any, payload: Dict[str, Any], *, kind: str) -> bool:
    checks = [
        ("turn", durable_row["turn"], payload["turn"]),
        ("faction", durable_row["faction"], payload["faction"]),
        ("source_name", durable_row["source_name"], payload["source_name"]),
        ("amount", durable_row["amount"], payload["amount"]),
        ("reason_code", durable_row["reason_code"], payload["reason_code"]),
        ("source", durable_row["source"], payload["source"]),
    ]
    for _label, left, right in checks:
        if not _null_safe_eq(left, right):
            return False
    if kind in ("direct", "kinship"):
        for field in ("axis", "base", "legitimacy_pct"):
            if not _null_safe_eq(durable_row[field], payload[field]):
                return False
    elif kind == "overdraw":
        for field in ("axis", "base", "legitimacy_pct"):
            if durable_row[field] is not None:
                return False
            if payload[field] is not None:
                return False
    else:
        return False
    return True

def _loads_lenient(
    raw: str, *, accepted_types: tuple[type, ...] = (dict,),
) -> Optional[Any]:
    """容错解析 JSON：剥代码围栏并截取首个受理容器。失败返回 None。"""
    t = (raw or "").strip()
    if t.startswith("```"):
        t = re.sub(r"^```[a-zA-Z]*\s*", "", t)
        t = re.sub(r"\s*```$", "", t).strip()
    starts = []
    if dict in accepted_types:
        starts.append((t.find("{"), "}"))
    if list in accepted_types:
        starts.append((t.find("["), "]"))
    starts = [(index, closer) for index, closer in starts if index >= 0]
    if not starts:
        return None
    i, closer = min(starts, key=lambda item: item[0])
    j = t.rfind(closer)
    if j <= i:
        return None
    body = t[i:j + 1]
    try:
        obj = json.loads(body)
    except (ValueError, TypeError):
        # 严格解析失败才做 JSONC 容错（CMR F8）：模型照 prompt 模板回带 // 行注释或尾逗号时救回。
        # 先严格、失败才清洗 —— 合法 JSON 不经清洗器。清洗器 quote-aware：串值里的 //、,}、://
        # 一律不动（#6，旧裸正则会误伤 "x,}"→"x}"、"a//b"→截断）。
        try:
            obj = json.loads(_strip_jsonc(body))
        except (ValueError, TypeError):
            return None
    return obj if isinstance(obj, accepted_types) else None

def _secret_metadata_from_command(text: str) -> Tuple[List[str], int]:
    tags: List[str] = []
    deadline = 0
    for raw_line in (text or "").splitlines():
        line = raw_line.strip()
        if not line:
            continue
        m_tags = re.match(r"^(?:标签|tag|tags)\s*[：:]\s*(.+)$", line, flags=re.IGNORECASE)
        if m_tags:
            for item in re.split(r"[,，、/;；\s]+", m_tags.group(1)):
                cleaned = item.strip()
                if cleaned and cleaned not in tags:
                    tags.append(cleaned)
            continue
        m_deadline = re.match(r"^(?:期限|限期|deadline)\s*[：:]\s*(.+)$", line, flags=re.IGNORECASE)
        if m_deadline:
            match = re.search(r"([+-]?\d+)\s*(?:个)?月", m_deadline.group(1))
            if match:
                deadline = max(0, min(int(match.group(1)), 36))
    return tags, deadline

def stopped_covert_effect(
