                if isinstance(value, bool) or isinstance(value, float):
                    raise ValueError("非整数 delta")
                delta = int(value)
            except (TypeError, ValueError):
                changes.append({
                    "power": row["name"], "field": str(raw_field),
                    "rejected": True, "category": "invalid_enum",
