def coerce_beyond_intent_flag(value: object) -> int:
    """闭世界肯定识别器：仅契约内肯定表示 →1；缺席/否定/空/畸形一律 →0。

    肯定：True / 非零 int·float / 肯定串集 {"1","true","yes","on","是","有","真"}。
    开放兜底永不得回归——畸形输入不得捏造肯定标记（0072/0118 真相层）。
    """
    if value is None:
        return 0
    if isinstance(value, bool):
        return 1 if value else 0
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return 1 if int(value) != 0 else 0
    text = str(value).strip().lower()
    return 1 if text in {"1", "true", "yes", "on", "是", "有", "真"} else 0

def knowledge_exclusion_targets_for_source(self, source_id: str) -> Dict[str, List[str]]:
    source = str(source_id or "")
    # Private briefs and retained bare secret-order sources share the
    # canonical exclusions persisted on secret_orders.
    match = re.fullmatch(r"secret_order(?:_brief)?:(\d+)", source)
    if match:
        row = self.conn.execute(
            "SELECT excluded_targets FROM secret_orders WHERE id=?",
            (int(match.group(1)),),
        ).fetchone()
        try:
            payload = json.loads((row["excluded_targets"] if row else "{}") or "{}")
        except (TypeError, ValueError):
            payload = {}
        return {"people": [str(x) for x in payload.get("people", [])],
                "offices": [str(x) for x in payload.get("offices", [])]}
    # #1829 reopen：公开说法排除目标与正文同表。
    match = re.fullmatch(r"public_saying:(\d+)", source)
    if match:
        row = self.conn.execute(
            "SELECT excluded_targets FROM public_sayings WHERE id=?",
            (int(match.group(1)),),
        ).fetchone()
        try:
            payload = json.loads((row["excluded_targets"] if row else "{}") or "{}")
        except (TypeError, ValueError):
            payload = {}
        return {"people": [str(x) for x in payload.get("people", [])],
                "offices": [str(x) for x in payload.get("offices", [])]}
    row = self.conn.execute(
        "SELECT excluded_targets FROM character_knowledge_sources WHERE source_id=?", (source,)
    ).fetchone()
    if row is None:
        return {"people": [], "offices": []}
    try:
        payload = json.loads(row["excluded_targets"] or "{}")
    except (TypeError, ValueError):
        payload = {}
    return {"people": [str(x) for x in payload.get("people", [])],
            "offices": [str(x) for x in payload.get("offices", [])]}

def resolve_commitment_origin_ref(
    self, state: GameState, supplied_ref: str, *, origin_kind: str = "",
) -> str:
    """承诺创建写端：有本回合已颁案卷时，origin 单向归一到案卷。"""
    supplied = str(supplied_ref or "").strip()
    if supplied.startswith("dossier:"):
        try:
            dossier_id = int(supplied.split(":", 1)[1])
        except (TypeError, ValueError):
            raise ValueError("commitment origin_ref 案卷 id 非法")
        if self.get_decree_dossier(dossier_id) is None:
            raise ValueError("commitment origin_ref 指向不存在案卷")
        return supplied
    from ming_sim.materials import SECRET_ORDER_ORIGIN_PREFIX, is_secret_order_origin

    if is_secret_order_origin(supplied):
        try:
            secret_order_id = int(supplied[len(SECRET_ORDER_ORIGIN_PREFIX):])
        except (TypeError, ValueError):
            raise ValueError("commitment origin_ref 密令 id 非法")
        dossier = self.get_dossier_for_secret_order(secret_order_id)
        if dossier is None:
            raise ValueError("commitment origin_ref 指向无案卷密令")
        return f"dossier:{int(dossier['id'])}"
    if str(origin_kind or "") == "decree":
        row = self.conn.execute(
            "SELECT COUNT(*) AS n FROM decree_dossiers WHERE created_turn=?",
            (int(state.turn),),
        ).fetchone()
        if row is not None and int(row["n"] or 0) > 0:
            raise ValueError(
                "承诺 origin_ref 必须由产出它的明确案卷携带 dossier:<id>"
            )
    return supplied

def _promulgation_decision_raw(row: dict) -> str:
    """Resolve the current promulgation-slot raw enum for a dossier row."""
    verdict = str(row.get("settlement_verdict") or "").strip()
    if verdict in DOSSIER_DECISION_CN:
        return verdict
    decision = str(row.get("promulgation_decision") or "").strip()
    if decision in DOSSIER_DECISION_CN:
        return decision
    if bool(row.get("was_force_promulgated")):
        return "force_promulgated"
    stigma = row.get("stigma") or []
    if isinstance(stigma, list):
        for item in stigma:
            if not isinstance(item, dict) or item.get("kind") != "midzhi":
                continue
            source = str(item.get("source_action") or "").strip()
            if source == "force_promulgated":
                return "force_promulgated"
            if source == "promulgated":
                return "promulgated"
            if source == "rejected":
                return "rejected"
    return decision

def audience_todo_lane(entry_kind: object) -> str:
    """entry_kind → 通道分派（唯一谓词）。"""
    kind = normalize_audience_entry_kind(entry_kind)
    if kind == ENTRY_KIND_STAGED:
        return _AUDIENCE_LANE_STAGED
    if kind == ENTRY_KIND_BREACH_PLEA:
        return _AUDIENCE_LANE_BREACH_PLEA
    if kind in (ENTRY_KIND_RUSH_REMONSTRANCE, ENTRY_KIND_GRACE_PLEA):
        return _AUDIENCE_LANE_URGE
    if kind == "covert_levy_exposure":
        return _AUDIENCE_LANE_COVERT_LEVY
    return _AUDIENCE_LANE_UNKNOWN

def parse_affair_declaration(
    raw: object,
    *,
    allowed: frozenset[str] | None = None,
) -> dict[str, object]:
    """Typed LLM declaration only. No prose parsing."""
    if not isinstance(raw, Mapping):
        raise ValueError("事务声明须为对象")
    attach = str(raw.get("attach") or "").strip()
    permitted = ATTACH_BIRTH | ATTACH_RESULT_CLOSE if allowed is None else allowed
    if attach not in permitted:
        if attach == _ATTACH_CLOSE:
            raise ValueError("本阶段不能了结事务")
        if attach in ATTACH_BIRTH and permitted == ATTACH_RESULT_CLOSE:
            raise ValueError("顶层事务声明只接受了结")
        raise ValueError("事务声明 attach 不在本阶段")
    if attach == _ATTACH_NEW:
        name = str(raw.get("name") or "")
        origin = str(raw.get("origin") or "")
        if not name or not origin:
            raise ValueError("新事务声明须有名字与起因")
        key = str(raw.get("birth_key") or "").strip()
        identity = str(raw.get("identity") or "").strip()
        out: dict[str, object] = {"attach": _ATTACH_NEW, "name": name, "origin": origin}
        if key:
            out["birth_key"] = key
        if identity:
            out["identity"] = identity
        return out
    try:
        affair_id = parse_positive_affair_id(raw.get("affair_id"))
    except (TypeError, ValueError) as exc:
        raise ValueError(
            "了结须有 affair_id" if attach == _ATTACH_CLOSE else "接到已开事务须有 affair_id"
        ) from exc
    return {"attach": attach, "affair_id": affair_id}

def _apply_authority_change_item(
    db: GameDB, state: GameState, item: Dict[str, object],
) -> Dict[str, object]:
    """Apply one production-slot authority grant/revoke under the #611 contract."""
    if "dossier_id" not in item or item.get("dossier_id") in (None, ""):
        raise ValueError("missing_dossier_source")
    try:
        dossier_id = _parse_sqlite_id(item.get("dossier_id"))
    except (TypeError, ValueError):
        raise ValueError("missing_dossier_source") from None
    if dossier_id <= 0 or db.get_decree_dossier(dossier_id) is None:
        raise ValueError("missing_dossier_source")
    if not db.dossier_authorizes_effects(dossier_id):
        raise ValueError("dossier_not_effect_eligible")
    op = str(item.get("动作") or item.get("op") or "").strip()
    if op not in _AUTHORITY_GRANT_OPS | _AUTHORITY_REVOKE_OPS:
        raise ValueError("授权变更动作只收授予/收回")

    if op in _AUTHORITY_GRANT_OPS:
        holder_id = str(item.get("holder_id") or "").strip()
        privilege = str(item.get("privilege") or item.get("权项") or "").strip()
        scope = str(item.get("scope") or item.get("事域") or "").strip()
        if not holder_id or not privilege or not scope:
            raise ValueError("授予项必须含 holder_id/privilege/scope")
        if privilege not in AUTHORITY_PRIVILEGE_SET:
            raise ValueError("授权权项不在首批枚举")
        kind, separator, target_id = scope.partition(":")
        if not separator or not kind or not target_id:
            raise ValueError("invalid_authority_scope")
        if not db.conn.execute(
            "SELECT 1 FROM characters WHERE name=?", (holder_id,)
        ).fetchone():
            raise ValueError("授权对象不在人物档")
        origin = db.find_authority_by_origin(
            dossier_id, holder_id=holder_id, privilege=privilege, scope=scope,
        )
        if origin is not None:
            # Origin idempotency is independent of current applicability: a
            # revoked or expired grant remains the same durable authority row.
            return {
                "动作": "授予",
                "authority_id": int(origin["id"]),
                "dossier_id": dossier_id,
                "holder_id": holder_id,
                "privilege": privilege,
                "scope": scope,
                "reason": "same_dossier_replay",
            }
        effective_raw = item.get("effective_turn", item.get("生效回合"))
        expires_raw = item.get("expires_turn", item.get("失效回合"))
        effective_turn = (
            int(state.turn) if effective_raw in (None, "")
            else _parse_sqlite_id(effective_raw)
        )
        expires_turn = (
            None if expires_raw in (None, "")
            else _parse_sqlite_id(expires_raw)
        )
        if expires_turn is not None and expires_turn < effective_turn:
            raise ValueError("授权失效回合不得早于生效回合")
        existing = db.find_active_authority(
            state.turn, holder_id=holder_id, privilege=privilege, scope=scope,
        )
        if existing is not None:
            raise ValueError("duplicate_active_authority")
        cursor = db.conn.execute(
            "INSERT INTO authority_records "
            "(holder_id,privilege,scope,effective_turn,expires_turn,dossier_id) "
            "VALUES (?,?,?,?,?,?)",
            (
                holder_id, privilege, scope, effective_turn, expires_turn,
                dossier_id,
            ),
        )
        authority_id = int(cursor.lastrowid)
        return {
            "动作": "授予",
            "authority_id": authority_id,
            "dossier_id": dossier_id,
            "holder_id": holder_id,
            "privilege": privilege,

def _apply_ordinary_entity_step(
    step_extracted: Dict[str, object],
    step_ordered: Dict[str, list[tuple[str, object]]],
    step_event_ids: dict[str, list[str]],
) -> None:
    step_new_armies = step_extracted.get("new_armies") or []
    declared = step_event_ids.get("new_armies") or []
    for idx, army_item in enumerate(step_new_armies):
        if not isinstance(army_item, dict):
            continue
        event_for_item = declared[idx] if idx < len(declared) else ""
        if event_for_item in strategic_event_referenced_ids:
            continue
        origin_ref = str(army_item.get("origin_ref") or "").strip()
        created_armies.extend(db.create_armies_from_extraction(
            state, [army_item], actor="档房", commit=commit_now,
            origin_ref=origin_ref, require_origin=True,
        ))
    for index, (region_id, raw_changes) in enumerate(step_ordered.get("region_delta") or []):
        if _effect_event_ids(
            "region_delta", index, strategic_event_referenced_ids, step_event_ids,
        ):
            continue
        origin_ref = str(raw_changes.get("origin_ref") or "").strip()
        payload = {k: v for k, v in raw_changes.items() if k != "origin_ref"}
        region_changes.extend(db.apply_region_deltas(
            state, pseudo_event, None, "档房", {region_id: payload},
            commit=commit_now, origin_ref=origin_ref, require_origin=True,
        ))
    for index, (army_id, raw_changes) in enumerate(step_ordered.get("army_delta") or []):
        if _effect_event_ids(
            "army_delta", index, strategic_event_referenced_ids, step_event_ids,
        ):
            continue
        army_changes.extend(_apply_extracted_army_delta(
            db, state, pseudo_event, army_id, raw_changes, commit_now=commit_now,
        ))

def _payload_owned_dossier_for_origin(db: GameDB, origin_ref: object) -> Optional[Dict[str, object]]:
    """Resolve an authorized dossier through the canonical ownership policy."""
    text = str(origin_ref or "").strip()
    if not text.startswith("dossier:"):
        return None
    try:
        dossier_id = _parse_sqlite_id(text.split(":", 1)[1])
    except ValueError:
        return None
    row = db.get_decree_dossier(dossier_id)
    if row is None or not db.dossier_authorizes_effects(dossier_id):
        return None
    try:
        payload = row.get("payload") or json.loads(str(row.get("payload_json") or "{}"))
    except (TypeError, ValueError):
        return None
    if not isinstance(payload, dict):
        return None
    if dossier_action_policy(row.get("action_type"), payload)["effect_owner"] != "payload":
        return None
    return {**row, "payload": payload}

def overlay_power_delta(power_id: object, raw_changes: object) -> None:
    pid = str(power_id or "").strip()
    if not pid or not isinstance(raw_changes, dict):
        return
    row = power_row(pid)
    if row is None:
        return
    for raw_field, value in raw_changes.items():
        field = POWER_FIELD_ALIASES.get(str(raw_field).strip(), str(raw_field).strip())
        if field in {"reason", "last_action"}:
            continue
        if field not in _PENDING_POWER_GATE_FIELDS:
            continue
        try:
            if isinstance(value, bool) or isinstance(value, float):
                raise ValueError("非整数 delta")
            delta = int(value)
        except (TypeError, ValueError):
            continue
        old_value = int(row[field])
        new_value = max(0, min(100, old_value + delta))
        if new_value == old_value:
            continue
        row[field] = new_value
        pending_power_fields.setdefault(pid, {})[field] = new_value

def project_court_roster_rows(
    rows: list[Any], knowledge: Dict[str, object], office_type: str,
) -> list[Any]:
    """Project complete structured roster rows through one character's view.

    The complete roster remains an internal query result.  A personnel-domain
    capability may expose it; otherwise only the reader's current role roster
    and people named in already-authorized events cross the output boundary.
    """
    world = knowledge.get("world") or {}
    if "personnel" in world:
        return list(rows)
    current_office_type = str(knowledge.get("office_type") or office_type or "")
    visible_event_text = "\n".join(
        "：".join(str(value) for value in (item.get("title"), item.get("body")) if value)
        for item in [*(knowledge.get("public_events") or []), *(knowledge.get("events") or [])]
    )
    return [
        row for row in rows
        if str(row["office_type"] or "") == current_office_type
        or str(row["name"] or "") in visible_event_text
    ]

def _resolve_inside(root: Path, rel: str) -> Path:
    root_r = root.resolve()
    raw = str(rel or "").strip()
    if not raw or raw in {".", "./"}:
        return root_r
    if Path(raw).is_absolute() or raw.startswith("~"):
        raise ValueError("材料路径越出目录")
    candidate = (root_r / raw).resolve()
    try:
        candidate.relative_to(root_r)
    except ValueError as exc:
        raise ValueError("材料路径越出目录") from exc
    return candidate

def dossier_id_in_origin(origin: object) -> Optional[int]:
    text = str(origin or "")
    if not text.startswith("dossier:"):
        return None
    raw = text[len("dossier:"):].split(":", 1)[0]
    if not raw.isdigit():
        return None
    return int(raw)

def is_secret_order_origin(origin: object) -> bool:
    """是否密令来源：origin/source_id 以 SECRET_ORDER_ORIGIN_PREFIX 开头。"""
    return str(origin or "").startswith(SECRET_ORDER_ORIGIN_PREFIX)

def _decree_ref_is_secret(db: Any, decree_ref: str) -> bool:
    from ming_sim.materials import is_secret_order_origin

    if is_secret_order_origin(decree_ref):
        return True
    prefix = "pending-action:"
    if not str(decree_ref).startswith(prefix):
        return False
    raw = str(decree_ref)[len(prefix):].split(":", 1)[0]
    if not raw.isdigit() or not hasattr(db, "conn"):
        return False
    row = db.conn.execute(
        "SELECT kind FROM pending_actions WHERE id=?", (int(raw),),
    ).fetchone()
    return row is not None and str(row["kind"] or "") == "secret_order"

def _dossier_for_decree_ref(db: Any, decree_ref: str) -> Optional[Dict[str, Any]]:
    from ming_sim.decree_forecast import decree_ref_for_dossier

    for dossier in db.list_decree_dossiers():
        if decree_ref_for_dossier(db, dossier) == decree_ref:
            return dossier
    if decree_ref.startswith("dossier:"):
        raw = decree_ref.split(":", 1)[1]
        if raw.isdigit():
            return db.get_decree_dossier(int(raw))
    return None

def _gazette_public_event(event: Any) -> bool:
    """作者经历投影：密令简报仍留在大臣自己的知识里，不写入作者可读经历。"""
    from ming_sim.materials import is_secret_order_origin

    if not isinstance(event, dict):
        return True
    kind = str(event.get("kind") or "")
    source = str(event.get("source_id") or "")
    if kind in {"secret_order", "secret_order_brief"}:
        return False
    return not is_secret_order_origin(source)

def _month_fact_materials(
