def _project_unsettled_summon_kind(
    db: Any, tags: Sequence[Any], person_name: str,
) -> str:
    """故事账 tags × 权威行止 → fresh | in_transit | waiting（只读推导，不落新 tag）。"""
    if TAG_IN_TRANSIT not in tags:
        return "fresh"
    from ming_sim.matching import is_capital_location

    row = db.conn.execute(
        "SELECT location, transit_to, status FROM characters WHERE name=?",
        (person_name,),
    ).fetchone()
    if row is None:
        return "in_transit"
    status = str(row["status"] or "active").strip() or "active"
    transit_to = str(row["transit_to"] or "").strip()
    location = str(row["location"] or "").strip()
    # ADR 0096 候见：在途 tag 且 active、无 transit、已在京 → waiting。
    if status == "active" and not transit_to and is_capital_location(location):
        return "waiting"
    return "in_transit"

def _dedicated_accounts(row: Any) -> List[str]:
    """专款账户读口（真实 producer 可达）：

    1. tags 含「专款:X」——承诺立项 new_issues.tags 既有写口（prompt 钉专款标签）
    2. ongoing_effects.economy[].account——承诺月供账户即专款流向
    """
    accounts: List[str] = []
    seen: Set[str] = set()

    def _add(raw: object) -> None:
        acc = str(raw or "").strip()
        if acc and acc not in seen:
            seen.add(acc)
            accounts.append(acc)

    try:
        keys = row.keys()
    except Exception:
        keys = []

    tags_raw = row["tags"] if "tags" in keys else "[]"
    try:
        tags = json.loads(tags_raw or "[]")
    except (TypeError, ValueError):
        tags = []
    if isinstance(tags, list):
        for tag in tags:
            t = str(tag or "").strip()
            if t.startswith("专款:"):
                _add(t.split(":", 1)[1].strip())

    ongoing_raw = row["ongoing_effects"] if "ongoing_effects" in keys else "{}"
    ongoing = loads_effect_dict(ongoing_raw or "{}")
    economy = ongoing.get("economy") if isinstance(ongoing, dict) else None
    if isinstance(economy, list):
        for item in economy:
            if isinstance(item, dict):
                _add(item.get("account"))
    return accounts

def held_authority_context(
    character: Character, db: GameDB, *, turn: Optional[int] = None,
) -> str:
    """大臣可见的在持授权定性摘要；裸 authority_records.id 永不入面。"""
    if turn is None:
        turn = int(db.load_state().turn)
    rows = db.list_active_authorities(int(turn), holder_id=character.name)
    if not rows:
        return ""
    labels: List[str] = []
    seen: set[str] = set()
    for row in rows:
        priv = str(row.get("privilege") or "").strip()
        if not priv or priv in seen:
            continue
        seen.add(priv)
        labels.append(_PRIVILEGE_QUALITATIVE.get(priv, priv))
    if not labels:
        return ""
    return f"【在持授权】{'、'.join(labels)}。"

