) -> Dict[str, object]:
    """#1896 4a 对查案密令的声明读口：查法/投入强度/所查事实/传话/知情反应。

    形状（ADR 0120 后出查案修订）——按人物当月真实办事声明，不读自由文本：
    - effort:   0..1 的**投入强度**（敷衍/停办 → 0）。只是"下了多大劲"，
                引擎另按承办人真实处境（能力/是否到差/未结差务带宽）折算本月实投。
                缺声明或不是数字 = **无效声明**（invalid），不是合法的零投入——
                明确停办只有一种写法：effort: 0。
    - fact_key: str，本月下手的罪证；人物没下手处就不给，代码不代选。
    - method:   查法（人物本月怎么查，原样落账）
    - tip_off:  {source} 真实通风报信：确有人经关系网把话递到被查者
    - spoliation: {effect, fact_key} 被查者知情后的毁证选择
    - suppression: {form} 被查者知情后的压案（行贿说项之类）声明

    奏报（memorial_text）不在此读口内：谎奏不造罪、不抹证（P6 实况/奏报分轨）。
    """
    item = sel if isinstance(sel, Mapping) else {}
    out: Dict[str, object] = {}
    raw_effort = item.get("effort", item.get("投入"))
    if raw_effort is None:
        out["invalid"] = "查案密令缺少 effort 声明（敷衍/停办请显式给 0）"
    else:
        intensity = _declared_intensity(raw_effort)
        if intensity is None:
            out["invalid"] = "查案密令的 effort 不是 0..1 的有限数字"
        else:
            out["intensity"] = intensity
    fact = str(item.get("fact_key", item.get("所查事实")) or "").strip()
    if fact:
        out["fact_key"] = fact
    raw_method = item["method"] if "method" in item else item.get("查法")
    if raw_method is not None and not isinstance(raw_method, (Mapping, list)):
        method = str(raw_method)
        if method != "":
            out["method"] = method
    tip = item.get("tip_off", item.get("通风报信"))
    if isinstance(tip, Mapping):
        source = str(tip.get("source", tip.get("递话人")) or "").strip()
        if source:
            out["tip_off"] = {"source": source}
    spoil = item.get("spoliation", item.get("毁证"))
    if isinstance(spoil, Mapping):
        effect = str(spoil.get("effect") or "harder").strip()
        if effect in ("harder", "gone"):
            out["spoliation"] = {
                "effect": effect,
                "fact_key": str(spoil.get("fact_key") or fact or "").strip(),
                "knowledge_source": str(
                    spoil.get("knowledge_source", spoil.get("知情来源")) or ""
                ),
            }
    suppress = item.get("suppression", item.get("压案"))
    if isinstance(suppress, Mapping):
        raw_form = suppress["form"] if "form" in suppress else suppress.get("方式")
        if raw_form is not None and not isinstance(raw_form, (Mapping, list)):
            form = str(raw_form)
            if form != "":
                out["suppression"] = {"form": form}
    return out

def _investigation_knowledge_known(
    db: Any, target: str, source: str, *, dossier_id: int = 0,
) -> bool:
    """被查者是否真知自己被查：须有**真实传话声明**＋账本里真实可递话的关系。

    开案本身不等于目标知情（那是"开案即全知"的漏洞）；关系边存在也不等于
    话真递到了——两者都得有：①本案 4a 声明过此人经关系网把话递到（落
    ``investigation_tips``，真实声明）；②此人在账本里确与该目标有关系边
    （0081 有向边，任意方向皆可：庇护、连坐、亲党皆有可能递话）。
    无声明／查无此人／无此边 → 确定性判未知情，其毁证与压案声明被拒。
    """
    who = str(source or "").strip()
    name = str(target or "").strip()
    if not who or not name:
        return False
    if who == name:
        return False  # 不作自己的信息来源
    if not db.conn.execute(
        "SELECT 1 FROM characters WHERE name=?", (who,),
    ).fetchone():
        return False
    # 传话记录与关系边必须是同一人。别人递过话，不能把未递话的关系人算成知情来源。
    if not any(
        str(tip.get("source") or "").strip() == who
        for tip in _investigation_tips(db, dossier_id, name)
    ):
        return False
    return any(
        str(edge["source"]) == who or str(edge["target"]) == who
        for edge in db.get_relation_edge_events(person=name)
    )

def _resolve_investigation_knowledge(
    db: Any, target: str, declared_source: str = "", *, dossier_id: int = 0,
) -> str:
    """解出被查者的知情来源（真实传话声明 ∩ 真实关系边），解不出返回空串。

    判据沿 ``_investigation_knowledge_known``：须有案卷已声明的真实传话，且
    递话人在账本里确与该目标有 0081 关系边。声明里带了 knowledge_source 就
    优先按它核（人物指名了谁递的话）；没带则回本案已声明的传话记录里找——
    知情是**跨月持续**的事实，上月真递到的话本月照样成立，不该因为本次
    声明没重复附上来源就当作不知情。
    """
    who = str(declared_source or "").strip()
    if who and _investigation_knowledge_known(
        db, target, who, dossier_id=int(dossier_id or 0),
    ):
        return who
    for tip in _investigation_tips(db, int(dossier_id or 0), str(target or "").strip()):
        source = str(tip.get("source") or "").strip()
        if source and _investigation_knowledge_known(
            db, target, source, dossier_id=int(dossier_id or 0),
        ):
            return source
    return ""

def attach_pending_action_endorsement(
    self, action_id: int, entry: Mapping[str, object], *, commit: bool = True,
) -> None:
    """#1842：把本轮背书挂进暂存载荷 endorsements 列表（不造待背书表）。"""
    aid = int(action_id)
    row = self.conn.execute(
        "SELECT payload_json, status FROM pending_actions WHERE id=?",
        (aid,),
    ).fetchone()
    if row is None:
        raise KeyError(f"暂存动作不存在：{aid}")
    if str(row["status"] or "") != "pending":
        raise ValueError(f"暂存动作状态不可挂背书：{row['status']}")
    try:
        payload = json.loads(str(row["payload_json"] or "{}"))
    except (TypeError, ValueError):
        payload = {}
    if not isinstance(payload, dict):
        payload = {}
    form = str(entry.get("form") or "").strip()
    endorser_id = str(entry.get("endorser_id") or "").strip()
    imperial = bool(entry.get("imperial", False))
    source_cid = int(entry.get("source_chat_turn_id") or 0)
    # 暂存阶段尚无 dossier：只验形式/人物/来源轮（与 _validate 同口径）。
    if form == "御笔手敕":
        imperial, endorser_id = True, ""
    if form not in {"会签", "当面站台", "御笔手敕"}:
        raise ValueError("背书形式非法")
    if form == "御笔手敕":
        if not imperial or endorser_id:
            raise ValueError("御笔手敕必须使用御笔标记且不得具名大臣")
    else:
        if imperial or not endorser_id:
            raise ValueError("会签/当面站台必须具名背书人")
        if self.conn.execute(
            "SELECT 1 FROM characters WHERE name=?", (endorser_id,),
        ).fetchone() is None:
            raise ValueError("背书人物不存在")
    if source_cid <= 0:
        raise ValueError("背书来源对话轮 id 须为正整数")
    if self.conn.execute(
        "SELECT 1 FROM chat_turns WHERE id=?", (source_cid,),
    ).fetchone() is None:
        raise ValueError("背书来源对话轮不存在")
    items = list(payload.get("endorsements") or [])
    if not isinstance(items, list):
        items = []
    # 同轮同形同人去重（INSERT OR IGNORE 同语义）。
    key = (form, endorser_id, imperial, source_cid)
    kept = []
    for raw in items:
        if not isinstance(raw, Mapping):
            continue
        k = (
            str(raw.get("form") or "").strip(),
            str(raw.get("endorser_id") or "").strip(),
            bool(raw.get("imperial", False)),
            int(raw.get("source_chat_turn_id") or 0),
        )
        if k == key:
            continue
        kept.append(dict(raw))
    kept.append({
        "form": form, "endorser_id": endorser_id,
        "imperial": imperial, "source_chat_turn_id": source_cid,
    })
    payload["endorsements"] = kept
    self.conn.execute(
        "UPDATE pending_actions SET payload_json=? WHERE id=?",
        (json.dumps(payload, ensure_ascii=False), aid),
    )
    if commit and (
        not bool(getattr(self.conn, "_commit_suspended", False))
        and int(getattr(self.conn, "_atomic_depth", 0) or 0) == 0
    ):
        self.conn.commit()

def find_active_authority(
    self, turn: int, *, holder_id: str, privilege: str, scope: str,
) -> Optional[Dict[str, object]]:
    """Return the in-hand row for the exact grant identity, if any."""
    holder_id = str(holder_id or "").strip()
    privilege = str(privilege or "").strip()
    scope = str(scope or "").strip()
    for row in self.list_active_authorities(turn, holder_id=holder_id):
        if (
            str(row.get("privilege") or "") == privilege
            and str(row.get("scope") or "") == scope
        ):
            return row
    return None

def project_applicable_authorities(
    self, turn: int, dossier: Mapping[str, object],
) -> List[Dict[str, object]]:
    """#611 unique applicability projection over durable authority rows.

    Actors = character executor ∪ roster 主办/协办 (never payload assignee).
    Domains = only the typed canonical key target_kind:target_id.
    """
    actors: set[str] = set()
    executor_id = str(dossier.get("executor_id") or "").strip()
    executor_kind = str(dossier.get("executor_kind") or "").strip()
    if executor_id and executor_kind in {"", "character"}:
        actors.add(executor_id)
    roster = dossier.get("participant_roster") or []
    if isinstance(roster, str):
        try:
            roster = json.loads(roster)
        except (TypeError, ValueError):
            roster = []
    if isinstance(roster, list):
        for entry in roster:
            if not isinstance(entry, dict):
                continue
            if str(entry.get("tier") or "").strip() not in {"主办", "协办"}:
                continue
            character_id = str(entry.get("character_id") or "").strip()
            if character_id:
                actors.add(character_id)
    target_kind = str(dossier.get("target_kind") or "").strip()
    target_id = str(dossier.get("target_id") or "").strip()
    domains: set[str] = set()
    if target_kind and target_id:
        domains.add(f"{target_kind}:{target_id}")
    if not actors or not domains:
        return []
    projected: List[Dict[str, object]] = []
    for holder_id in sorted(actors):
        for row in self.list_active_authorities(int(turn), holder_id=holder_id):
            if str(row.get("scope") or "") not in domains:
                continue
            projected.append({
                "id": int(row["id"]),
                "holder_id": str(row["holder_id"]),
                "privilege": str(row["privilege"]),
                "scope": str(row["scope"]),
                "effective_turn": int(row["effective_turn"]),
                **(
                    {"expires_turn": int(row["expires_turn"])}
                    if row.get("expires_turn") is not None else {}
                ),
            })
    projected.sort(key=lambda item: int(item["id"]))
    return projected

def resolve_commitment_origin_ref(
    self, state: GameState, supplied_ref: str, *, origin_kind: str = "",
) -> str:
    """承诺创建写端：有本回合已颁案卷时，origin 单向归一到案卷。"""
    supplied = str(supplied_ref or "").strip()
    if supplied.startswith("dossier:"):
        try:
            dossier_id = int(supplied.split(":", 1)[1])
        except (TypeError, ValueError):
            raise ValueError("commitment origin_ref 案卷 id 非法")
        if self.get_decree_dossier(dossier_id) is None:
            raise ValueError("commitment origin_ref 指向不存在案卷")
        return supplied
    from ming_sim.materials import SECRET_ORDER_ORIGIN_PREFIX, is_secret_order_origin

    if is_secret_order_origin(supplied):
        try:
            secret_order_id = int(supplied[len(SECRET_ORDER_ORIGIN_PREFIX):])
        except (TypeError, ValueError):
            raise ValueError("commitment origin_ref 密令 id 非法")
        dossier = self.get_dossier_for_secret_order(secret_order_id)
        if dossier is None:
            raise ValueError("commitment origin_ref 指向无案卷密令")
        return f"dossier:{int(dossier['id'])}"
    if str(origin_kind or "") == "decree":
        row = self.conn.execute(
            "SELECT COUNT(*) AS n FROM decree_dossiers WHERE created_turn=?",
            (int(state.turn),),
        ).fetchone()
        if row is not None and int(row["n"] or 0) > 0:
            raise ValueError(
                "承诺 origin_ref 必须由产出它的明确案卷携带 dossier:<id>"
            )
    return supplied

def dossier_action_policy(action_type: object, payload=None):
    """Return canonical policy, including the documented inner-treasury exemption."""
    action = str(action_type or "")
    policy = dict(DOSSIER_ACTION_POLICY[action])
    if action == "grant_allocation":
        payload = payload or {}
        grant_action = str(payload.get("grant_action") or "").strip()
        cadence = str(payload.get("cadence") or "").strip()
        if grant_action in {"加衔", "荫叙"}:
            policy["execution_surface"] = "terminal"
            return policy
        if str(payload.get("account") or "") == "内库":
            policy.update(external_review=False, effect_owner="immediate")
        if cadence == "每月":
            policy["execution_surface"] = "terminal"
            return policy
        surface = str(payload.get("execution_surface") or "in_transit")
        if surface not in {"immediate", "in_transit"}:
            raise ValueError("拨帑旨意 execution_surface 非法")
        policy["execution_surface"] = surface
    return policy

def qualitative_midzhi_markers(row: dict) -> list[str]:
    markers: list[str] = []
    mode = str(row.get("mode") or "").strip()
    if mode == "midzhi":
        markers.append("中旨")
    stigma = row.get("stigma") or []
    if isinstance(stigma, list):
        for item in stigma:
            if not isinstance(item, dict) or item.get("kind") != "midzhi":
                continue
            source = str(item.get("source_action") or "").strip()
            if source == "force_promulgated":
                label = "批红强颁"
            elif source == "rejected":
                label = "中旨打回"
            else:
                label = "中旨"
            if label not in markers:
                markers.append(label)
    if bool(row.get("was_force_promulgated")) and "批红强颁" not in markers:
        markers.append("批红强颁")
    return markers

def _todo_origin_ref(todo: Dict[str, object], meta_origin: str = "") -> str:
    """#1783：案卷 due todo（commitment_ref=0）origin 在 payload；承诺 todo 仍读 issue。"""
    payload = todo.get("payload_json") or {}
    if isinstance(payload, dict):
        raw = str(payload.get("origin_ref") or "").strip()
        if raw:
            return raw
        did = payload.get("dossier_id")
        try:
            if int(did or 0) > 0:
                return f"dossier:{int(did)}"
        except (TypeError, ValueError):
            pass
    return str(meta_origin or "").strip()

def _eval_gate_key(key: str, metrics: Dict[str, int], db: GameDB) -> Optional[float]:
    """把 gate key 解析成一个数值。形式：
      - 'metric_name'                           → metrics[key]
      - 'region.<id>.<field>'                   → regions 表
      - 'region.<id1>|<id2>|.<field>.<agg>'     → 多省聚合 (max/min/avg/sum)
      - 'army.<id>.<field>' / 多军 + agg
      - 'building.<id>.<field>' / 多建筑 + agg
      - 'power.<id>.<field>' / 多 + agg
      - 'character.<name>.<field>' / 多人物 + agg
      - 'event.<id>.terminal_state'               → event_triggers 表文本门专用
      - 'class.<name>.<field>'                  → classes 表全国汇总 (region_id='')
      - 'class.<name>@<region>.<field>'         → classes 表省级
      - 'class.<name>@<r1>|<r2>|.<field>.<agg>' → 多省同阶级聚合
      - 'event.<id>.triggered'                  → event_triggers 账，已发=1 未发=0
    解析失败/数据缺失返回 None（gate 视为不通过，由调用方处理）。
    """
    if "." not in key:
        if key in metrics:
            try:
                return int(metrics[key])
            except (TypeError, ValueError):
                return None
        return None
    parts = key.split(".")
    table = parts[0]
    if table not in GATE_TABLES:
        return None
    # 末段可能是 agg，先抽出
    agg = None
    if parts[-1] in _GATE_AGG_FUNCS:
        agg = parts[-1]
        parts = parts[:-1]
    if len(parts) < 3:
        return None
    field = parts[-1]
    id_segment = ".".join(parts[1:-1])
    field = _gate_sql_field(table, field, key, kind="numeric")
    if table == "class" and "@" in id_segment and "|" in id_segment.split("@", 1)[1]:
        # 简写：class.<name>@<r1>|<r2>|<r3>.<field> → 展开成 [name@r1, name@r2, name@r3]
        cname, rest = id_segment.split("@", 1)
        ids = [f"{cname}@{r}" for r in rest.split("|") if r]
    else:
        ids = id_segment.split("|") if "|" in id_segment else [id_segment]
        ids = [x for x in ids if x]
    if not ids:
        return None
    # class 表的 id 是 name 或 name@region；其它表 id 就是行 id
    values: List[float] = []
    for cid in ids:
        row = None
        if table == "event":
            if cid not in db.content.event_by_id:
                return None
            values.append(1 if db.has_event_terminal_state(cid, "triggered") else 0)
            continue
        if table == "region":
            row = db.conn.execute(f"SELECT {field} FROM regions WHERE id = ?", (cid,)).fetchone()
        elif table == "army":
            row = db.conn.execute(f"SELECT {field} FROM armies WHERE id = ?", (cid,)).fetchone()
        elif table == "building":
            row = db.conn.execute(f"SELECT {field} FROM buildings WHERE id = ?", (cid,)).fetchone()
        elif table == "power":
            row = db.conn.execute(f"SELECT {field} FROM powers WHERE id = ?", (cid,)).fetchone()
        elif table == "faction":
            # factions 表主键是 name（中文，如 阉党），field 取 leverage/satisfaction
            row = db.conn.execute(f"SELECT {field} FROM factions WHERE name = ?", (cid,)).fetchone()
        elif table == "character":
            row = db.conn.execute(f"SELECT {field} FROM characters WHERE name = ?", (cid,)).fetchone()
        elif table == "class":
            if "@" in cid:
                cname, rid = cid.split("@", 1)
            else:
                cname, rid = cid, ""
            row = db.conn.execute(
                f"SELECT {field} FROM classes WHERE name = ? AND region_id = ?",
                (cname, rid),
            ).fetchone()
        if row is None:
            return None
        try:
            values.append(float(row[0]))

def _event_chain_impossible_reason(ev: Event, terminal_records: Dict[str, Dict[str, str]], state: GameState) -> str:
    allowed_states: Dict[str, set[str]] = {}
    forbidden_states: Dict[str, set[str]] = {}
    allowed_outcomes: Dict[str, set[str]] = {}
    forbidden_outcomes: Dict[str, set[str]] = {}

    def _format_values(values: set[str]) -> str:
        return "|".join(sorted(values))

    def allow_states(upstream_id: str, state_names: set[str], *, raw_key: object, raw_cond: str) -> None:
        if not state_names:
            return
        existing = allowed_states.get(upstream_id)
        if existing is None:
            allowed_states[upstream_id] = set(state_names)
            return
        narrowed = existing & state_names
        if not narrowed:
            raise SettlementAbort(
                "事件链正向终态门互相矛盾："
                f"{upstream_id} 已要求 {{{_format_values(existing)}}}，"
                f"又要求 {{{_format_values(state_names)}}}（{raw_key} {raw_cond}）",
                turn=state.turn,
                stage="event_chain_config",
            )
        allowed_states[upstream_id] = narrowed

    def allow_state(upstream_id: str, state_name: str, *, raw_key: object, raw_cond: str) -> None:
        allow_states(upstream_id, {state_name}, raw_key=raw_key, raw_cond=raw_cond)

    def allow_outcomes(upstream_id: str, outcomes: set[str], *, raw_key: object, raw_cond: str) -> None:
        if not outcomes:
            return
        existing = allowed_outcomes.get(upstream_id)
        if existing is None:
            allowed_outcomes[upstream_id] = set(outcomes)
            return
        narrowed = existing & outcomes
        if not narrowed:
            raise SettlementAbort(
                "事件链正向结局门互相矛盾："
                f"{upstream_id} 已要求 {{{_format_values(existing)}}}，"
                f"又要求 {{{_format_values(outcomes)}}}（{raw_key} {raw_cond}）",
                turn=state.turn,
                stage="event_chain_config",
            )
        allowed_outcomes[upstream_id] = narrowed

    def forbid_state(upstream_id: str, state_name: str) -> None:
        forbidden_states.setdefault(upstream_id, set()).add(state_name)

    for raw_key, raw_cond in (ev.trigger_gate or {}).items():
        m = _EVENT_GATE_KEY_RE.match(str(raw_key))
        if not m:
            continue
        upstream_id, field = m.group(1), m.group(2)
        cond = str(raw_cond).strip()
        if field == "triggered":
            num = re.match(r"^(>=|<=|>|<|==)\s*(-?\d+)$", cond)
            if not num:
                continue
            op, value = num.group(1), int(num.group(2))
            dependency_kind = _event_triggered_numeric_dependency_kind(op, value)
            if dependency_kind == "positive":
                allow_state(upstream_id, "triggered", raw_key=raw_key, raw_cond=cond)
            elif dependency_kind == "negative":
                forbid_state(upstream_id, "triggered")
            elif dependency_kind == "neither":
                raise SettlementAbort(
                    f"事件链 triggered 门在布尔域 {{0,1}} 上永不满足：{raw_key} {cond}",
                    turn=state.turn,
                    stage="event_chain_config",
                )
            continue
        text = re.match(r"^(==|!=|in=)\s*(.+)$", cond)
        if not text:
            continue
        op, value = text.group(1), text.group(2).strip()
        values = {part.strip() for part in value.split("|") if part.strip()}
