    for row in rows:
        try:
            excluded_names = json.loads(row["excluded_names"] or "[]")
        except (TypeError, ValueError):
            excluded_names = []
        if not isinstance(excluded_names, list):
            excluded_names = []
        item = {
            "title": row["title"], "body": row["body"],
            "source_id": row["source_id"], "excluded_names": excluded_names,
        }
