def _write_locations_in_source(source: str, relative: str) -> set[str]:
    """Scan one module's source for direct ``characters``-mutating execute() SQL.

    Handles both plain string literals AND f-strings (``ast.JoinedStr``): an
    f-string execute arg like ``f"DELETE FROM characters WHERE ..."`` is the
    Call arg as a whole, so it matches directly (its inner ``Constant`` parts
    have the JoinedStr as parent — not the Call — so they are correctly skipped
    by ``_is_sql_execute_argument``; before this an f-string-only write point
    escaped the inventory scan entirely)."""
    tree = ast.parse(source)
    parents: dict[ast.AST, ast.AST] = {}
    for parent in ast.walk(tree):
        for child in ast.iter_child_nodes(parent):
            parents[child] = parent
    found: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            sql_src = node.value
        elif isinstance(node, ast.JoinedStr):
            sql_src = "".join(
                v.value for v in node.values
                if isinstance(v, ast.Constant) and isinstance(v.value, str)
            )
        else:
            continue
        if not _is_sql_execute_argument(node, parents):
            continue
        sql = " ".join(sql_src.split())
        if not any(marker in sql for marker in _MUTATING_SQL_MARKERS):
            continue
        function_name = _enclosing_function_name(node, parents)
        found.add(_inventory_location(relative, function_name, sql))
    return found

def _validated_settlement_origin(
    db: Any, origin_ref: object, allowed_dossier_ids: Any = None,
) -> str:
    """结算口 provenance 守门：只收**精确 canonical 值**——原始值恰为「盘面自发」
    哨兵字面，或恰为已颁且授权效果的 ``dossier:<id>`` 字面。

    dossier 引用受**双重闭集合取**（V2）：id 须属本批冻结输入
    ``allowed_dossier_ids``（apply_score_extraction 既有 dossier_ids_at_input，
    None/缺集/非集合一律按空闭集 fail-closed，不从 live DB 重建），且经既有
    GameDB.effect_origin_rejection 授权。盘面自发不受该集合影响。

    不做任何归一（ADR 0015 显式优于推断）：带首尾空白的变体（" 盘面自发 "、
    "\n盘面自发\t"、空白包裹的 dossier 引用）一律逐项拒收留痕，不 strip 后
    放行。精确匹配同时封死自带 round/turn 的伪造值（origin_round 一律由当前
    回合同步绑定，TD-1 不容伪造）；案卷授权核验复用
    GameDB.effect_origin_rejection 既有 API，不另立平行守门。"""
    if not isinstance(origin_ref, str):
        raise ValueError(f"来源引用必须为字符串，得 {type(origin_ref).__name__}")
    if origin_ref == SETTLEMENT_ORIGIN_SENTINEL:
        return origin_ref
    match = _DOSSIER_ORIGIN_RE.fullmatch(origin_ref)
    if match is None:
        raise ValueError(
            f"来源引用非法（只收精确「{SETTLEMENT_ORIGIN_SENTINEL}」或已授权"
            f" dossier:<id>，不归一首尾空白）：{origin_ref!r}"
        )
    frozen_ids = (
        allowed_dossier_ids
        if isinstance(allowed_dossier_ids, (set, frozenset)) else set()
    )
    if int(match.group("id")) not in frozen_ids:
        raise ValueError(
            f"来源案卷不在本批冻结输入（dossier 闭集拒收）：{origin_ref}"
        )
    if db.effect_origin_rejection(origin_ref) is not None:
        raise ValueError(f"origin_ref 非法：{origin_ref}")
    return origin_ref

def canonical_choice(raw: object) -> dict:
    if not isinstance(raw, dict):
        raise ValueError("批语须为对象")
    choice = dict(raw)
    key = choice.get("decision_key")
    if not isinstance(key, str) or not key:
        raise ValueError("批语缺 decision_key")
    for field in ("label", "hint", "note", "action", "dossier_decision"):
        if field in choice and not isinstance(choice[field], str):
            raise ValueError(f"批语 {field} 须为字符串")
    return choice

def produce_memorials(session, chain: dict, *, source) -> None:
    from ming_sim.month_chain import _save_chain
    from ming_sim.applier import atomic

    if chain.get("rescript_drafted"):
        return
    db, state = session.db, session.state
    officers = triage_officers(db)
    backlog = [row for row in db.list_rescript_drafts(status="revision_pending")
               if int(row["answered_turn"]) < int(state.turn)]
    if officers:
        data = parse_agent_json(run_rescript_text(session, officers=officers, backlog=backlog), "rescript-draft")
        actor = next((r for r in officers if r["name"] == data.get("actor_name")), None)
        if actor is None or not isinstance(data.get("items"), list) or not isinstance(data.get("revisions"), list):
            raise LLMContractError("票拟须具名在职分拣人并交 items/revisions")
        items = [_memorial(item, actor) for item in data["items"]]
        originals = {f"rescript_draft:{r['turn']}:{r['idx']}": r for r in backlog}
        revisions = [_memorial(item, actor) for item in data["revisions"]]
        keys = [item.get("decision_key") for item in revisions]
        if any(not isinstance(key, str) for key in keys) or len(keys) != len(set(keys)) or set(keys) != set(originals):
            raise LLMContractError("改票须逐一回指待改原案，不增删原案身份")
    else:
        items, revisions, originals = [], [], {}
    with atomic(db):
        db.append_rescript_drafts(int(state.turn), items, revisions=[
            {**item, "turn": originals[item["decision_key"]]["turn"],
             "idx": originals[item["decision_key"]]["idx"]} for item in revisions
        ])
        chain["rescript_drafted"] = True
        _save_chain(db, int(state.turn), chain, source=source)

def prune_auto_saves(saves_dir: str, campaign_id: str, keep_turns: int = AUTO_SAVE_KEEP_TURNS) -> None:
    """清理自动存档：只清同一个 campaign_id，按 turn 分组，绝不碰手动存档。"""
    import os as _os
    import re as _re

    if not _os.path.isdir(saves_dir):
        return
    legacy_auto = _re.compile(rf"^{_re.escape(AUTO_SAVE_PREFIX)}\d{{4}}_\d{{2}}_t\d{{4}}_.+\.db$")
    for f in _os.listdir(saves_dir):
        if legacy_auto.match(f):
            try:
                _os.remove(_os.path.join(saves_dir, f))
            except OSError:
                pass
    campaign_id = (campaign_id or "").strip()
    if not campaign_id:
        return
    buckets: Dict[int, List[str]] = {}
    for f in _os.listdir(saves_dir):
        if not (f.startswith(f"{AUTO_SAVE_PREFIX}{campaign_id}_") and f.endswith(".db")):
            continue
        m = _re.search(r"_t(\d+)_", f)
        if not m:
            continue
        buckets.setdefault(int(m.group(1)), []).append(f)
    keep = max(1, int(keep_turns or 1))
    keep_turn_nums = set(sorted(buckets.keys(), reverse=True)[:keep])
    for turn_num, files in buckets.items():
        if turn_num in keep_turn_nums:
            continue
        for stale in files:
            try:
                _os.remove(_os.path.join(saves_dir, stale))
            except OSError:
                pass

def bind_decision_options(options: object) -> Dict[str, Dict[str, object]]:
    """Bind normalized labels to stored options, rejecting ambiguous decisions."""
    bound: Dict[str, Dict[str, object]] = {}
    if not isinstance(options, list):
        raise ValueError("decision options 须为 list")
    for option in options:
        if not isinstance(option, dict):
            continue
        label = str(option.get("label") or "")
        if not label.strip() or any(key.strip() == label.strip() for key in bound):
            raise ValueError(f"decision option label 为空或重复：{label!r}")
        bound[label] = option
    return bound

def parse_decision_blocks(text: str) -> List[Dict[str, object]]:
    """读取世界段请旨机标中的决策列表，不改写原文。

    每块须含 title/context/options（2-3 项，每项 label + 可选 hint）。
    解析失败的块忽略，最多取 MAX_DECISIONS_PER_TURN 条。
    """
    decisions: List[Dict[str, object]] = []
    for m in _DECISION_RE.finditer(text or ""):
        if len(decisions) >= MAX_DECISIONS_PER_TURN:
            break
        try:
            obj = json.loads(m.group(1))
        except Exception:
            continue
        if not isinstance(obj, dict):
            continue
        title = str(obj.get("title") or "")
        raw_opts = obj.get("options")
        if not title or not isinstance(raw_opts, list):
            continue
        options: List[Dict[str, object]] = []
        for o in raw_opts:
            if not isinstance(o, dict):
                continue
            label = str(o.get("label") or "")
            if not label:
                continue
            try:
                action_type = validate_season_option(o)
            except ValueError:
                options = []
                break
            option: Dict[str, object] = {
                "label": label,
                "hint": str(o.get("hint") or ""),
            }
            # Deterministic financial options carry their executable payload;
            # label/hint remain presentation only.
            for key in season_option_fields(action_type):
                if key in o:
                    option[key] = action_type if key == "action_type" else o[key]
            options.append(option)
        try:
            bind_decision_options(options)
        except ValueError:
            continue
        if len(options) < 2:  # 至少给 2 个选项才算有效抉择
            continue
        decision = {
            "title": title,
            "context": str(obj.get("context") or ""),
            "options": options[:3],
        }
        explicit_event_id = str(obj.get("event_id") or "").strip()
        origin_ref = str(obj.get("origin_ref") or "").strip()
        event_id = explicit_event_id or origin_ref
        if event_id:
            decision["event_id"] = event_id
        # 只在 id 来自 origin_ref 时留下该键。世界请旨钉定就地排除它；
        # 显式 event_id 的块与原先一样只有 event_id。
        if origin_ref and not explicit_event_id:
            decision["origin_ref"] = origin_ref
        decisions.append(decision)
    return decisions

