    if priv:
        matches = [
            m for m in matches if str(m.get("privilege") or "") == priv
        ]
    if len(matches) != 1:
        return None
    return matches[0]

def assert_responsible_bodies_org_only(
    bodies: Sequence[str],
    *,
    known_person_names: Iterable[str] = (),
    current_minister: str = "",
) -> None:
    """机关/职司语义：个人名与当前召对大臣不得入 responsible_bodies。"""
    persons = {str(n).strip() for n in known_person_names if str(n or "").strip()}
    minister = str(current_minister or "").strip()
    if minister:
        persons.add(minister)
    if not persons:
        return
    for body in bodies:
        name = str(body or "").strip()
        if name and name in persons:
            raise ValueError(f"responsible_bodies 禁个人名：{name}")

def minister_speaker_role(
    minister_name: str,
    character: Any = None,
    db: Any = None,
) -> str:
    """ADR 0033 objective characterization for recovery speaker (not name/office alone)."""
    from ming_sim.context import faction_context_with_db, minister_dossier
    from ming_sim.models import Character

    ch = character
    if not isinstance(ch, Character) and db is not None:
        content = getattr(db, "content", None)
        roster = getattr(content, "characters", None) if content is not None else None
        if isinstance(roster, dict):
            found = roster.get(str(minister_name or "").strip())
            if isinstance(found, Character):
                ch = found
    if isinstance(ch, Character):
        parts = [
            f"{ch.name}，{ch.office}",
            minister_dossier(ch),
        ]
        if db is not None:
            parts.append(faction_context_with_db(ch, db))
        return "\n".join(p for p in parts if str(p or "").strip())
    office = str(getattr(ch, "office", "") or "").strip() if ch is not None else ""
    office_type = (
        str(getattr(ch, "office_type", "") or "").strip() if ch is not None else ""
    )
    bits = [p for p in (str(minister_name or "").strip(), office or office_type) if p]
    return "，".join(bits) or "大臣"

def re_split_bodies(text: str) -> List[str]:
    """下议机关名分隔：逗号/顿号/斜线/分号/竖线（三缝共用）。"""
    return _RESPONSIBLE_BODY_SPLIT.split(str(text or ""))

def require_explicit_xiexang_fields(
    *,
    amount: object = 0,
    account: str = "",
    purpose: str = "",
    target_kind: str = "",
    target_id: str = "",
    cadence: str = "",
) -> Dict[str, Any]:
    """#1503 单一权威接缝：严格验形并归一 typed 字段。"""
    from ming_sim.strict_types import strict_int

    facts: list = []

    def _note(field: str, *, current: object, expected: object) -> None:
        facts.append({"field": field, "current": current, "expected": expected})

    try:
        n = strict_int(amount, accept_numeric_strings=False)
    except ValueError:
        n = 0
    if n <= 0:
        _note("amount", current=amount, expected={"type": "positive_int"})
    # #1620：太仓→国库唯一权威 resolve_grant_account；此处不再平行 if。
    canonical_account = resolve_grant_account(grant_action="协饷", account=account)
    if canonical_account not in {"国库", "内库"}:
        _note("account", current=account, expected=["国库", "内库"])
    purpose_cur = str(purpose or "").strip()
    if purpose_cur != "补饷":
        _note("purpose", current=purpose_cur or purpose, expected="补饷")
    canonical_target_kind = str(target_kind or "").strip()
    if canonical_target_kind not in XIEXIANG_TARGET_KINDS:
        _note(
            "target_kind",
            current=canonical_target_kind or target_kind,
            expected=sorted(XIEXIANG_TARGET_KINDS),
        )
    target_id_cur = str(target_id or "").strip()
    if not target_id_cur:
        _note("target_id", current=target_id, expected={"nonempty_str": True})
    cadence_value = str(cadence or "").strip()
    if cadence_value and cadence_value not in {"一次性", "每月"}:
        _note(
            "cadence",
            current=cadence_value,
            expected=["一次性", "每月", ""],
        )
    if facts:
        raise IncompleteXiexangPayloadError(field_failures=facts)
    return {
        "amount": n,
        "account": canonical_account,
        "purpose": "补饷",
        "target_kind": canonical_target_kind,
        "target_id": target_id_cur,
    }

def str_field(data: Dict[str, object], key: str, path: str) -> str:
    value = data.get(key)
    if not isinstance(value, str) or not value.strip():
        raise SystemExit(f"设定字段应为非空字符串：{path}.{key}")
    return value.strip()

def _validate_summon_method(method: str, *, default: str) -> str:
    """校验召法白名单（summon_enter / record_summon_in_transit 共用单一真源）。"""
    m = str(method or default).strip()
    if m not in SUMMON_METHODS:
        raise AudienceNightError(
            f"召法非法：{m!r}（须为 {'/'.join(sorted(SUMMON_METHODS))}）",
            code="bad_summon_method",
        )
    return m

def assert_persons_not_dead(
    db: Any,
    names: Sequence[str],
    *,
    context: str = "在场",
) -> None:
    dead: List[str] = []
    for name in names:
        n = str(name or "").strip()
        if not n:
            continue
        if _character_status(db, n) == "dead":
            dead.append(n)
    if not dead:
        return
    message = f"死账校验失败：已殁者不可{context}：{('、'.join(dead))}"
    pack = write_audience_error_pack(
        kind="dead_present",
        message=message,
        detail={"dead": dead, "context": context},
    )
    raise AudienceNightError(
        message, code="dead_present", error_pack_path=pack,
        detail={"dead": dead, "context": context},
    )

def list_arrived_unsettled_summons(db: Any) -> List[Dict[str, Any]]:
    """Project in-transit summons whose original non-capital journey has completed.

    waiting（抵京候见）不进续程 payload；inactive 由 retire 结清，不投续程。
    每人每阶段只向读端供一份续赴京事实；多 origin ledger 行不合并。
    """
    from ming_sim.matching import is_capital_location

    arrived: List[Dict[str, Any]] = []
    for item in list_unsettled_summons(db):
        if item["kind"] != "in_transit":
            continue
        row = db.conn.execute(
            "SELECT location, transit_to, status FROM characters WHERE name=?",
            (item["person_name"],),
        ).fetchone()
        if row is None or str(row["transit_to"] or "").strip():
            continue
        status = str(row["status"] or "active").strip() or "active"
        if status != "active":
            continue
        destination = str(row["location"] or "").strip()
        if not destination:
            continue
        # kind=in_transit 已排除 capital waiting；此处再挡一层同地续程。
        if is_capital_location(destination):
            continue
        arrived.append({
            "person_name": item["person_name"],
            "original_destination": destination,
            "origin_id": item["origin_id"],
            "source_entry_id": item["entry_id"],
            "required_fact": "抵原地后续赴京",
        })
    return _one_per_person(arrived)

def settle_applied_arrived_summons(
    db: Any, applied: Dict[str, Any],
) -> List[str]:
    """结清已由 canonical applier 成功续启赴京的在途召旨。

    只认 applied_person_changes 中未拒收且 transit_to=beizhili 的成功行止；
    同人全部 kind=in_transit 未结 origin 一并结清。失败/空 applied 为 no-op。
    外层 settle atomic 使行止与结清同成同败（_should_commit 已为 False）。
    """
    accepted = {
        str(item.get("name") or item.get("人物") or "").strip()
        for item in (applied.get("applied_person_changes") or [])
        if isinstance(item, dict)
        and not item.get("rejected")
        and str(item.get("transit_to") or item.get("去向") or "").strip() == "beizhili"
    }
    accepted.discard("")
    if not accepted:
        return []
    settled: List[str] = []
    for item in list_unsettled_summons(db):
        # 月度判官只收 in_transit origin；成功续启后 transit_to 已变，
        # 后置投影不再是 arrived，故按 person∈accepted 结清。
        if item["kind"] != "in_transit" or item["person_name"] not in accepted:
            continue
        origin = str(item["origin_id"])
        if settle_summon_origin(db, origin):
            settled.append(origin)
    return settled

