def _scan_remove_sponsor(db: Any, state: Any) -> List[int]:
    """撤人：主办罢/调（status 离岗 或 职务变动而仍 active）。"""
    written: List[int] = []
    for row in list_active_commitments(db):
        cid = int(row["id"])
        if has_pending_plea(db, cid, breach_kind=BREACH_KIND_REMOVE_SPONSOR):
            continue
        sponsors = _sponsor_names_for_commitment(db, row)
        if not sponsors:
            continue
        removed: List[str] = []
        transferred: List[str] = []
        for s in sponsors:
            if _sponsor_dismissed(db, s):
                removed.append(s)
            elif _sponsor_transferred(db, s, row):
                transferred.append(s)
        hit = removed + transferred
        if not hit:
            continue
        origin = str(row["origin_ref"] or "")
        who = "、".join(hit[:3])
        kind_word = "罢调" if removed and transferred else ("罢" if removed else "调")
        tid = write_breach_plea_todo(
            db, state,
            commitment_ref=cid,
            breach_kind=BREACH_KIND_REMOVE_SPONSOR,
            reason=f"主办{who}{kind_word}，人亡政息",
            target_dossier_id=int(parse_dossier_id(origin) or 0),
            extra={
                "removed_sponsors": removed,
                "transferred_sponsors": transferred,
            },
        )
        if tid:
            written.append(tid)
    return written

def _sponsor_transferred(db: Any, name: str, commitment_row: Any) -> bool:
    """调：status 仍 active，但职务已变（相对承诺/案卷记录的主办职）。"""
    char = db.conn.execute(
        "SELECT status, office FROM characters WHERE name=?", (name,),
    ).fetchone()
    if char is None:
        return False
    if str(char["status"] or "") != "active":
        return False
    current_office = str(char["office"] or "").strip()
    # character_offices 备档
    co = db.conn.execute(
        "SELECT office_title FROM character_offices WHERE character_name=?",
        (name,),
    ).fetchone()
    if co is not None:
        current_office = str(co["office_title"] or current_office).strip() or current_office

    # 承诺 / 案卷侧只取 office 身份字段；role 是职分自由措辞，不得与 current_office 比语义。
    expected = ""
    try:
        roster = json.loads(commitment_row["participant_roster"] or "[]")
    except (TypeError, ValueError):
        roster = []
    if isinstance(roster, list):
        for item in roster:
            if not isinstance(item, dict):
                continue
            if str(item.get("character_id") or "").strip() != name:
                continue
            if item.get("tier") != "主办":
                continue
            # #1847: no role fallback, no substring/length proxy for "is office".
            expected = str(item.get("office") or item.get("office_title") or "").strip()
            break

    # 案卷 executor office 快照（结构化 office 字段，非自由 role）
    if not expected:
        did = parse_dossier_id(
            commitment_row["origin_ref"] if "origin_ref" in commitment_row.keys() else ""
        )
        if did is not None:
            drow = db.conn.execute(
                "SELECT executor_id, payload_json FROM decree_dossiers WHERE id=?",
                (int(did),),
            ).fetchone()
            if drow is not None and str(drow["executor_id"] or "") == name:
                try:
                    payload = json.loads(drow["payload_json"] or "{}")
                except (TypeError, ValueError):
                    payload = {}
                if isinstance(payload, dict):
                    expected = str(
                        payload.get("executor_office")
                        or payload.get("office")
                        or ""
                    ).strip()

    # office_change_records：有调任记录且当前 office 与承诺侧 office 身份不等
    oc = db.conn.execute(
        """
        SELECT office_title FROM office_change_records
        WHERE character_name=? ORDER BY id DESC LIMIT 1
        """,
        (name,),
    ).fetchone()
    if oc is not None and expected:
        latest = str(oc["office_title"] or "").strip()
        if latest and expected and latest != expected and current_office != expected:
            return True
    # Exact office-identity inequality only — no length/substring free-text classify.
    if expected and current_office and expected != current_office:
        return True
    return False

def _submit_cli_decisions(session: GameSession, result) -> str:
    """CLI 文书批语：皇帝选择拟批或亲笔；不自动代选。"""
    if result is None or not result.awaiting:
        return "" if result is None else result.report
    choices = []
    for row in list(result.decisions or []) or session.pending_decisions():
        print(f"\n{row['title']}\n{row['context']}")
        for idx, option in enumerate(row["options"], 1):
            print(f"{idx}. {option['label']} {option.get('hint', '')}")
        explicit = str(row.get("event_id") or "").startswith(("dossier:", "deliberation:"))
        while True:
            raw = input("拟批编号 / 亲笔批语" + ("（m 另旨·中旨）" if row["kind"] == "rescript_draft" else "") + "：")
            choice = {"decision_key": row["decision_key"]}
            if raw.isdecimal() and 1 <= int(raw) <= len(row["options"]):
                option = row["options"][int(raw) - 1]
                choice.update(label=option["label"], hint=option.get("hint", ""))
                if explicit:
                    choice["action"] = option.get("dossier_decision") or option.get("action") or ""
                choice["note"] = input("附批（可空）：")
                break
            if not explicit and raw.strip():
                if raw == "m" and row["kind"] == "rescript_draft":
                    choice.update(action="midzhi", note=input("御笔旨意："))
                    if not choice["note"].strip():
                        continue
                else:
                    choice["note"] = raw
                break
            print("请选择编号；不代选。")
        choices.append(choice)
    return session.submit_hitl_choices(choices, write_gate=_cli_write_gate(session))

def choose_minister(session: GameSession) -> Optional[Character]:
    """列大臣，皇帝选一位。返回 None 表示退朝去审阅诏书。"""
    characters = session.content.characters
    # 可召名册资格单真源 _is_summonable_court_minister（#1317 r2 DRY：与 can_summon/
    # list_ministers/visible_in_court/事实块同口径）。offstage 未登场另滤——到 debut 年月现身。
    # 后宫不经朝臣可召谓词、走 can_summon 专路，CLI 大臣单亦不列后宫（与 web consorts 分栏同形）。
    resolve = session.db.resolve_power_id
    names = [
        name for name in characters
        if _is_summonable_court_minister(characters[name], resolve_power_id=resolve)
        and session.db.get_character_status(name)[0] != "offstage"
    ]
    print("\n可召见大臣：")
    for idx, name in enumerate(names, 1):
        c = characters[name]
        status, _ = session.db.get_character_status(name)
        tag = "" if status == "active" else f"  [{_STATUS_LABEL.get(status, status)}]"
        print(f"{idx}. {c.name}（{c.office}，{c.faction}）{tag}")
    while True:
        raw = input("召见谁？输入编号或姓名，quit 退朝审阅诏书，exit 退出游戏：").strip()
        if not raw:
            print("请输入编号或姓名。")
            continue
        lowered = raw.lower()
        if lowered in EXIT_COMMANDS:
            raise ExitGame
        if lowered in COURT_BREAK_COMMANDS:
            return None
        candidate: Optional[Character] = None
        if raw.isdigit() and 1 <= int(raw) <= len(names):
            candidate = characters[names[int(raw) - 1]]
        elif raw in characters:
            candidate = characters[raw]
        else:
            matches = [
                c for c in characters.values()
                if raw in c.name or raw in c.office or raw in c.office_type
                or raw in c.faction or raw in c.aliases
            ]
            if len(matches) == 1:
                candidate = matches[0]
            elif len(matches) > 1:
                print("这句话能对应多位大臣，请再说具体一点，或直接输编号。")
                continue
        if candidate is None:
            # #670：未知/未注册人物不得临时旁路入殿；须 ADR 0038 持久入册后再走 admission。
            try:
                candidate = session.summon_character(raw)
            except ValueError:
                print("请输入有效编号或姓名。")
                continue
        # 召对总闸 can_summon（含宗藩拒 + 非 active 拒）——按名/编号/模糊任一路解析到的人都过此闸，
        # 与 web /chat、LLM summon 工具同口径集中守（cmr R6：CLI 选臣菜单原先只查 status、漏宗藩）。
        decision = session.consume_audience_admission(
            candidate,
            origin_id=f"cli:initial:{session.state.turn}:{candidate.name}",
        )
        if not decision.allowed:
            # 资格失败仍见 reason；成功记召 reason 为空，不喷固定承旨句。
            if decision.reason:
                print(decision.reason)
            continue
        return candidate

