    return "+".join(
        str(it["name"])
        for it in budget[acc][direction]
        if it.get("budget_key") == budget_key and int(it["amount"])
    )

def _normalize_dossier_mode(cls, value: object) -> str:
    mode = value.strip() if isinstance(value, str) else value
    if not isinstance(mode, str) or mode not in cls.DOSSIER_MODES:
        raise ValueError(f"案卷 mode 非法：{mode}")
    return mode

def _normalize_dossier_report_origin(
    cls, origin: object, *, is_terminal: bool = False,
) -> str:
    raw = str(origin or "").strip()
    if not raw:
        return (
            cls.DOSSIER_REPORT_ORIGIN_VERDICT
            if is_terminal
            else cls.DOSSIER_REPORT_ORIGIN_MONTHLY
        )
    prefix = cls.DOSSIER_REPORT_ORIGIN_NS
    if not raw.startswith(prefix) or not raw[len(prefix):].strip():
        raise ValueError("奏报 origin 须带 dossier-report 命名空间前缀")
    return raw

def _parts(acc: str, direction: str, names: tuple[str, ...]) -> str:
    present = [name for name in names if _amt(acc, direction, name)]
    return "+".join(present) if present else "无"

def _recommendation_snapshot_ready(
    self, state: GameState, payload: Dict[str, object], *, minister_name: str = "",
) -> bool:
    """载荷无荐人，或 staged 快照仍与当前盘面一致时为 True。

    #1583：唯一校验真源仍是 validate_recommendation_snapshot；本 helper 只
    组装 payload 形状，不复制第二套判断。
    """
    recommendation = payload.get("recommendation")
    if recommendation is None:
        return True
    if not isinstance(recommendation, dict):
        return False
    staged_candidate = recommendation.get("candidate")
    recommender = str(
        recommendation.get("recommender") or minister_name or ""
    ).strip()
    if not isinstance(staged_candidate, dict) or not recommender:
        return False
    name = str(payload.get("name") or "").strip()
    from ming_sim.recommendations import validate_recommendation_snapshot
    return (
        staged_candidate.get("name") == name
        and validate_recommendation_snapshot(
            self, state, recommender, staged_candidate,
        )
    )

def _validate_participant_roster_references(
    self, roster: Iterable[Mapping[str, object]],
) -> None:
    """Enforce ADR 0053 character primary-key references at the DB write seam."""
    entries = list(roster)
    referenced = {
        str(value).strip()
        for item in entries
        for value in (item.get("character_id"), item.get("delegator_id"))
        if str(value or "").strip()
    }
    if not referenced:
        return
    placeholders = ",".join("?" for _ in referenced)
    known = {
        str(row["name"])
        for row in self.conn.execute(
            f"SELECT name FROM characters WHERE name IN ({placeholders})",
            tuple(referenced),
        ).fetchall()
    }
    from ming_sim.participant_roster import is_non_person_participant_name

    def _roster_ref_error(label: str, name: str) -> ValueError:
        # #1380：拒「皇帝」等非人通称时给人话提示，禁裸「参与人物不存在：皇帝」
        if is_non_person_participant_name(name):
            return ValueError(
                f"{label}不存在：{name}。"
                f"人物参与人须为朝堂名册中的大臣姓名，"
                f"不可填「{name}」等非人通称或机构名。"
            )
        return ValueError(
            f"{label}不存在：{name}。"
            f"请填写朝堂名册中已有的大臣姓名。"
        )

    for item in entries:
        character_id = str(item.get("character_id") or "").strip()
        delegator_id = str(item.get("delegator_id") or "").strip()
        if character_id not in known:
            raise _roster_ref_error("参与人物", character_id)
        if delegator_id and delegator_id not in known:
            raise _roster_ref_error("委派人", delegator_id)

def append_decree_dossier_participants(
    self, dossier_id: int, participants: Iterable[object], *,
    state: Optional[GameState] = None, commit: bool = True,
) -> List[Dict[str, object]]:
    """Append ADR 0053 roster entries without replacing durable members."""
    row = self.conn.execute(
        "SELECT participant_roster,action_type,decree_text FROM decree_dossiers WHERE id=?",
        (int(dossier_id),),
    ).fetchone()
    if row is None:
        raise KeyError(f"案卷不存在：{dossier_id}")
    try:
        existing_raw = json.loads(row["participant_roster"] or "[]")
    except (TypeError, ValueError):
        existing_raw = []
    existing = self._normalize_participant_roster(
        existing_raw if isinstance(existing_raw, list) else []
    )
    additions = self._normalize_participant_roster(participants, strict_structured=True)
    self._validate_participant_roster_references(additions)
    by_character = {str(item["character_id"]): item for item in existing}
    added: List[Dict[str, object]] = []
    for item in additions:
        character_id = str(item["character_id"])
        prior = by_character.get(character_id)
        if prior is not None:
            if prior != item:
                raise ValueError(f"参与人物已在案且机械档不同：{character_id}")
            continue
        by_character[character_id] = item
        added.append(item)
    merged = existing + added
    self._validate_dossier_delegations(merged)
    self._validate_participant_roster_references(merged)
    if added:
        archive_keys: set[str] = set()
        raw_keys_row = self.conn.execute(
            "SELECT office_archive_keys FROM decree_dossiers WHERE id=?",
            (int(dossier_id),),
        ).fetchone()
        raw_keys = (
            raw_keys_row["office_archive_keys"] if raw_keys_row is not None else None
        ) or "[]"
        parsed_keys = json.loads(raw_keys)
        if not isinstance(parsed_keys, list):
            raise ValueError(
                f"office_archive_keys 须为 JSON 数组：dossier {int(dossier_id)}"
            )
        archive_keys = {str(item) for item in parsed_keys}
        if str(row["action_type"] or "") != "secret_order":
            for item in added:
                if str(item.get("tier") or "") != "主办":
                    continue
                lead_name = str(item.get("character_id") or "")
                lead = self.conn.execute(
                    "SELECT office,office_type,location FROM characters WHERE name=?",
                    (lead_name,),
                ).fetchone()
                if lead is None:
                    continue
                key = self._office_archive_key(
                    lead["office"], lead["office_type"],
                    location=lead["location"] if "location" in lead.keys() else "",
                    character_name=lead_name,
                )
                if key:
                    archive_keys.add(key)
        self.conn.execute(
            "UPDATE decree_dossiers SET participant_roster=?,office_archive_keys=?,"
            "updated_at=CURRENT_TIMESTAMP WHERE id=?",
            (
                json.dumps(merged, ensure_ascii=False),
                json.dumps(sorted(archive_keys), ensure_ascii=False),
                int(dossier_id),
            ),
        )
        if state is not None and str(row["action_type"] or "") != "secret_order":
            for item in added:
                identity = ":".join(str(item.get(key) or "-") for key in (
                    "character_id", "tier", "role", "delegator_id",
                ))

def list_decree_dossiers(
    self, *, status: Optional[str] = None, target_kind: Optional[str] = None,
    target_id: Optional[object] = None,
) -> List[Dict[str, object]]:
    clauses: List[str] = []
    params: List[object] = []
    if status is not None:
        if status not in self._DOSSIER_STATUSES:
            raise ValueError(f"案卷 status 非法：{status}")
        clauses.append("status=?")
        params.append(status)
    if target_kind is not None:
        clauses.append("target_kind=?")
        params.append(str(target_kind))
    if target_id is not None:
        clauses.append("target_id=?")
        params.append(str(target_id))
    where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
    rows = self.conn.execute(
        f"SELECT * FROM decree_dossiers{where} ORDER BY id", params
    ).fetchall()
    return [self._dossier_row(row) for row in rows]

def normalize_office(office: str) -> str:
    """官职多职统一为半角逗号分隔：旧「兼/兼掌/兼署」与全角「，」「、」一律归一逗号，
    去空分项、去重、保序。是 office 字段落库的唯一规范化入口——所有写 characters.office
    的路径都过它，保证去重/顶缺时能按逗号分项匹配。"""
    s = (office or "").strip()
    if not s:
        return ""
    s = s.replace("兼掌", ",").replace("兼署", ",").replace("兼", ",")
    s = s.replace("，", ",").replace("、", ",")
    seen: set = set()
    parts: List[str] = []
    for p in (x.strip() for x in s.split(",")):
        if p and p not in seen:
            seen.add(p)
            parts.append(p)
    return ",".join(parts)

def record_dossier_progress(
    self,
    dossier_id: int,
    turn: int,
    progress_band: str,
    memorial_text: str,
    *,
    is_terminal: bool = False,
    origin: str = "",
    commit: bool = True,
) -> int:
    """Append one reported-progress entry; write path splits by physical track.

    Secret-order dossiers stay on secret_orders.dossier_progress_json (#566).
    Non-secret execution-surface dossiers use dossier_reported_progress (#619).
    Reported rows never enter apply (ADR 0073).
    """
    dossier = self.get_decree_dossier(int(dossier_id))
    band = str(progress_band or "").strip()
    text = str(memorial_text or "")
    if dossier is None:
        raise ValueError("案卷不存在")
    if not band or not text.strip():
        raise ValueError("进展档和密奏均不能为空")
    origin_norm = self._normalize_dossier_report_origin(
        origin, is_terminal=bool(is_terminal),
    )
    secret_order_id = dossier.get("secret_order_id")
    if secret_order_id:
        return self._record_secret_dossier_progress(
            int(dossier_id), int(secret_order_id), int(turn), band, text,
            is_terminal=bool(is_terminal), origin=origin_norm, commit=commit,
        )
    payload = {}
    try:
        loaded = json.loads(str(dossier.get("payload_json") or "{}"))
        if isinstance(loaded, dict):
            payload = loaded
    except (TypeError, ValueError):
        payload = {}
    if not self._dossier_has_execution_surface(dossier.get("action_type"), payload):
        raise ValueError("非执行面案卷不可挂奏报")
    return self._record_general_dossier_progress(
        int(dossier_id), int(turn), band, text,
        is_terminal=bool(is_terminal), origin=origin_norm, commit=commit,
    )

def set_fiscal_config_batch(self, values: Dict[str, int], commit: bool = True) -> None:
    owns_transaction = self.owns_transaction() if commit else False
    normalized = {str(k or "").strip(): int(v) for k, v in values.items()}
    self.validate_fiscal_config_values(normalized)
    self.conn.executemany(
        "UPDATE fiscal_config SET value = ? WHERE key = ?",
        [(value, key) for key, value in normalized.items()],
    )
    if commit and owns_transaction:
        self.conn.commit()

def treasury_budget_summary(self, state: "GameState | None" = None) -> str:
    # 三套口径统一：直接调 flows.compute_budget_lines（唯一定额源），此处只负责拼文本。
    from ming_sim.flows import compute_budget_lines  # 局部 import 避免与 flows 顶层循环依赖
    st = state if state is not None else self.load_state("")
    budget = compute_budget_lines(self, st)

    def _sum(acc: str, direction: str) -> int:
        return sum(int(it["amount"]) for it in budget[acc][direction])

    def _amt(acc: str, direction: str, name: str) -> int:
        return sum(int(it["amount"]) for it in budget[acc][direction] if it["name"] == name)

    def _amt_key(acc: str, direction: str, budget_key: str) -> int:
        return sum(
            int(it["amount"])
            for it in budget[acc][direction]
            if it.get("budget_key") == budget_key
        )

    def _names_key(acc: str, direction: str, budget_key: str) -> str:
        return "+".join(
            str(it["name"])
            for it in budget[acc][direction]
            if it.get("budget_key") == budget_key and int(it["amount"])
        )

    def _parts(acc: str, direction: str, names: tuple[str, ...]) -> str:
        present = [name for name in names if _amt(acc, direction, name)]
        return "+".join(present) if present else "无"

    gk_in, gk_out = _sum("国库", "income"), _sum("国库", "expense")
    nk_in, nk_out = _sum("内库", "income"), _sum("内库", "expense")
    army_pay_amt = _amt_key("国库", "expense", "army_pay")
    army_pay_label = _names_key("国库", "expense", "army_pay")
    gk_income_names = _parts(
        "国库", "income",
        ("起运", "田赋辽饷盐商", "盐税", "商税"),
    )
    # 军饷科目取数认 budget_key；呈现名跟预算行 name（玩家/摘要同源）。
    other_expense = (
        ("中央军饷", "太仓亏空", "宗室禄米", "百官俸禄", "工部", "赈灾备用", "建筑维护")
        if self.is_substrate_hub_fiscal_engine_enabled()
        else ("宗室禄米", "百官俸禄", "工部", "赈灾备用", "建筑维护")
    )
    expense_present = [
        army_pay_label if army_pay_amt else "",
        *(name for name in other_expense if _amt("国库", "expense", name)),
    ]
    gk_expense_names = "+".join(name for name in expense_present if name) or "无"
    return (
        f"{TURN_UNIT}度预算基准：国库入{format_money(gk_in)}"
        f"（{gk_income_names}；建筑产出{format_money(_amt('国库', 'income', '建筑产出'))}）"
        f"出{format_money(gk_out)}"
        f"（{gk_expense_names}；军饷"
        f"{format_money(army_pay_amt)}+"
        f"建筑维护{format_money(_amt('国库', 'expense', '建筑维护'))}）"
        f"净{format_money_delta(gk_in - gk_out)}；"
        f"内库入{format_money(nk_in)}"
        f"出{format_money(nk_out)}"
        f"（内廷维护{format_money(_amt('内库', 'expense', '建筑维护'))}）"
        f"净{format_money_delta(nk_in - nk_out)}。"
    )

def validate_joint_liability_affected_parties(
    self, affected_parties: object, outcome: str,
) -> None:
    """显式 affected_parties：validate_affected_parties 全键 + 档位贴合终值映射。

    仅作契约§5/AC⑥校验门闩，不驱动机械写路；适配器在落库前调用一次。
    """
    primary = self._EXECUTION_OUTCOME_INTENSITY.get(str(outcome or "").strip())
    if primary is None:
        raise ValueError("连坐 affected_parties 仅接受 degraded/failed/transformed 终值")
    allowed = {primary}
    downgraded = self._INTENSITY_DOWNGRADE.get(primary)
    if downgraded:
        allowed.add(downgraded)
    faction_names = {
        str(row["name"]) for row in self.conn.execute("SELECT name FROM factions")
    }
    class_names = {
        str(row["name"])
        for row in self.conn.execute("SELECT DISTINCT name FROM classes")
    }
    validate_affected_parties(
        affected_parties,
        faction_names=faction_names,
        class_names=class_names,
    )
    for party in affected_parties:  # type: ignore[union-attr]
        if str(party.get("intensity") or "") not in allowed:
            raise ValueError("affected_parties intensity 须与执行终值固定映射一致")

def _assert_commission_grant_target_exists(
    db: Any, target_kind: str, target_id: str,
) -> None:
    """拨帑目标必须是账上真实体；查无 → KeyError（hallucinated_id）。"""
    kind = str(target_kind or "").strip()
    tid = str(target_id or "").strip()
    if kind == "region":
        row = db.conn.execute("SELECT 1 FROM regions WHERE id=?", (tid,)).fetchone()
        if row is None:
            raise KeyError(f"地区不存在：{tid}")
        return
    if kind == "character":
        _assert_characters_exist(db, [tid])
        return
    if kind == "army":
        row = db.conn.execute("SELECT 1 FROM armies WHERE id=?", (tid,)).fetchone()
        if row is None:
            raise KeyError(f"军队不存在：{tid}")
        return
    if kind == "issue":
        try:
            iid = int(tid)
        except (TypeError, ValueError) as exc:
            raise KeyError(f"事项不存在：{tid}") from exc
        row = db.conn.execute("SELECT 1 FROM issues WHERE id=?", (iid,)).fetchone()
        if row is None:
            raise KeyError(f"事项不存在：{tid}")
        return

def _attach_commission_staging_fields(
    payload: Dict[str, Any], item: Mapping[str, object], *, turn: int,
) -> None:
    """透传既有 staging 字段：assignee / participant_roster / due_turn。

    字段可在交办顶层，或挂在 grant 对象内（与 stage_grant_allocation_candidate
    kwargs 同口径）。期限单源＝due_turn；deadline_months / end_turn 仅作换算输入。
    """
    grant = item.get("grant") if isinstance(item.get("grant"), Mapping) else {}
    lead = str(
        item.get("assignee")
        or item.get("assignee_id")
        or item.get("assignee_name")
        or (grant.get("assignee") if grant else "")
        or (grant.get("assignee_id") if grant else "")
        or ""
    ).strip()
    if lead:
        payload["assignee"] = lead
    roster = item.get("participant_roster")
    if not isinstance(roster, list) and grant:
        roster = grant.get("participant_roster")
    if isinstance(roster, list) and roster:
        payload["participant_roster"] = list(roster)
    elif lead and not isinstance(payload.get("participant_roster"), list):
        payload["participant_roster"] = [{
            "character_id": lead, "tier": "主办", "role": "", "delegator_id": None,
        }]
    due_src = item if item.get("due_turn") not in (None, "", 0) else grant
    end_src = item if item.get("end_turn") not in (None, "", 0) else grant
    months_src = (
        item if item.get("deadline_months") not in (None, "", 0) else grant
    )
    # 与 stage_assignment / stage_grant 同缝：相对月数或绝对回合 → 绝对 due_turn。
    absolute_due = _assignment_absolute_end_turn(
        int(turn),
        end_turn=(due_src or item).get("due_turn") or (end_src or item).get("end_turn") or 0,
        deadline_months=(months_src or item).get("deadline_months") or 0,
    )
    if absolute_due > int(turn):
        payload["due_turn"] = absolute_due

def _attach_recommendation_fields(
    db: Any,
    state: Any,
    item: Mapping[str, object],
    payload: Optional[Dict[str, Any]],
    *,
    default_recommender: str,
) -> Optional[Tuple[str, str]]:
    """把荐人声明挂到任命载荷。无 recommendation 字段 → 无操作。

    返回 (reason, category) 表示拒收；None 表示已挂或无需挂。
    """
    reco_raw = item.get("recommendation")
    if not reco_raw:
        return None
    if payload is None:
        return ("荐人声明须附任命载荷", "invalid_shape")
    if not isinstance(reco_raw, Mapping):
        return ("荐人载荷须为对象", "invalid_shape")
    recommender = str(
        reco_raw.get("recommender") or default_recommender or ""
    ).strip()
    reason = reco_raw.get("reason")
    if reason is None:
        reason = ""
    if not isinstance(reason, str):
        return ("荐词 reason 须为字符串", "invalid_shape")
    if not reason.strip():
        return ("荐人须附非空荐词缘由", "invalid_shape")
    if not recommender:
        return ("荐人声明缺荐者", "invalid_shape")
    target = str(payload.get("name") or "").strip()
    office = str(payload.get("office") or "").strip()
    if not target or not office:
        return ("荐人任命缺 name/office", "invalid_shape")
    row = next(
        (
            candidate
            for candidate in db.list_recommendation_candidates(state, recommender)
            if candidate["name"] == target
        ),
        None,
    )
    if row is None:
        return (
            f"被荐者不在荐者派系/见闻可及范围内：{target}",
            "invalid_state",
        )
    # 荐词原句逐字落库；strip 仅作判空谓词（ADR 0082 / #635 Y2）。
    payload["reason"] = reason
    payload["recommendation"] = {
        "candidate_kind": row["candidate_kind"],
        "basis": row["basis"],
        "recommender": recommender,
        "candidate": row,
    }
    if row.get("faction"):
        payload.setdefault("faction", row["faction"])
    return None

def _dispatch_endorsements(
    db: Any, state: Any, raw: object, *, night_id: int,
    chat_turn_id: int, source: Provenance,
) -> SectionResult:
    """#1842：每轮转译声明对暂存交办的会签/当面站台/御笔手敕。

    挂在 pending_actions.payload_json["endorsements"]，成案时继承到案卷；
    目标已成案（迟到转译）则按 pending_action_id 直写案卷背书。来源为本轮。
    """
    from ming_sim.strict_types import strict_int

    items, rejected = _section_items(raw, label="背书声明", source=source)
    applied: List[Any] = []
    ctid = int(chat_turn_id or 0)
    if ctid <= 0 and items:
        for item in items:
            _reject(
                rejected, item, "背书须绑定本轮对话源", "missing_ref", source,
            )
        return SectionResult(applied=applied, rejected=rejected)
    for item in items:
        try:
            action_id = strict_int(
                item.get("action_id"), accept_numeric_strings=False,
            )
        except (TypeError, ValueError):
            action_id = 0
        form = str(item.get("form") or "").strip()
        endorser_id = str(item.get("endorser_id") or "").strip()
        if action_id <= 0 or form not in {"会签", "当面站台", "御笔手敕"}:
            _reject(
                rejected, item,
                "背书须含正 action_id 与 会签|当面站台|御笔手敕",
                "invalid_shape", source,
            )
            continue
        imperial = form == "御笔手敕"
        if imperial:
            endorser_id = ""
        elif not endorser_id:
            _reject(
                rejected, item, "会签/当面站台必须具名背书人",
                "invalid_shape", source,
            )
            continue
        row = db.conn.execute(
            "SELECT id, night_id, status, payload_json FROM pending_actions "
            "WHERE id=? AND turn=?",
            (action_id, int(state.turn)),
        ).fetchone()
        if row is None or int(row["night_id"] or 0) != int(night_id):
            _reject(
                rejected, item, f"暂存动作不属本夜暂存清单：{action_id}",
                "missing_ref", source,
            )
            continue
        entry = {
            "form": form,
            "endorser_id": endorser_id,
            "imperial": imperial,
            "source_chat_turn_id": ctid,
        }
        status = str(row["status"] or "")
        if status == "pending":
            try:
                db.attach_pending_action_endorsement(
                    action_id, entry, commit=False,
                )
            except (TypeError, ValueError, KeyError) as exc:
                _reject(rejected, item, str(exc), "invalid_item", source)
                continue
        elif status == "committed":
            drow = db.conn.execute(
                "SELECT id FROM decree_dossiers WHERE pending_action_id=? "
                "ORDER BY id", (action_id,),
            ).fetchall()
            if not drow:
                _reject(
                    rejected, item,
                    f"已成案暂存无对应案卷：{action_id}",
                    "missing_ref", source,

def _dispatch_rushes(
    db: Any,
    state: Any,
    raw: object,
    *,
    minister_name: str,
    source: Provenance,
    source_chat_turn_id: int = 0,
) -> SectionResult:
    """催办声明 → 既有 pending 催办写口（密令 / 分段承诺，ADR 0078）。

    ``source_chat_turn_id``（#1890）：暂存行的来源轮，随交办身份落库。"""
    items, rejected = _section_items(raw, label="催办声明", source=source)
    applied: List[Any] = []
    for item in items:
        target_kind = str(item.get("target_kind") or "").strip()
        try:
            target_id = int(item.get("target_id") or 0)
        except (TypeError, ValueError):
            target_id = 0
        if target_kind not in {"commitment", "secret_order"} or target_id <= 0:
            _reject(
                rejected, item,
                "催办须含 target_kind=commitment|secret_order 与正 target_id",
                "invalid_shape", source,
            )
            continue
        try:
            raw_deadline = item.get("deadline_months", 1)
            deadline = max(0, min(int(raw_deadline if raw_deadline is not None else 1), 36))
        except (TypeError, ValueError):
            deadline = 1
        reason = str(item.get("reason") or "")
        actor = str(minister_name or "").strip() or _commission_fallback_actor(db)
        if target_kind == "commitment":
            row = db.conn.execute(
                "SELECT id, status, stages_json FROM issues WHERE id=?",
                (target_id,),
            ).fetchone()
            if row is None:
                _reject(rejected, item, f"催办目标承诺不存在：{target_id}", "hallucinated_id", source)
                continue
            if str(row["status"] or "") != "active":
                _reject(
                    rejected, item,
                    f"催办目标承诺状态不容许：{row['status']}",
                    "invalid_state", source,
                )
                continue
            try:
