def _rescript_decisions(
    verdicts: List[Dict[str, object]],
    dossiers: List[Dict[str, object]],
) -> List[Dict[str, object]]:
    """Turn rejected promulgation verdicts into the existing HITL decision rail."""
    by_id = {int(row["id"]): row for row in dossiers}
    decisions: List[Dict[str, object]] = []
    for verdict in verdicts:
        if str(verdict.get("decision") or "") != "rejected":
            continue
        dossier_id = int(verdict.get("dossier_id") or 0)
        dossier = by_id.get(dossier_id)
        if dossier is None:
            continue
        opponents = [
            str(item.get("key") or "").strip()
            for item in verdict.get("primary_opponents", [])
            if isinstance(item, dict) and str(item.get("key") or "").strip()
        ]
        opposition = "、".join(opponents)
        decisions.append({
            "event_id": f"dossier:{dossier_id}",
            "title": "批红待裁",
            "context": str(dossier.get("decree_text") or ""),
            "rejection_reason": str(verdict.get("reason") or ""),
            "opposition": opposition,
            # hint（非 note）：前端 isPendingDecision / DecisionOption 认 hint；
            # dossier_id/dossier_decision 是批红能力字段，点选必须原样回传（#1490）。
            "options": [
                *([] if verdict.get("midzhi_unpromulgatable") is True else [{
                    "label": "强颁",
                    "hint": "改走中旨强行颁出，并承担中旨代价",
                    "dossier_id": dossier_id,
                    "dossier_decision": "force_promulgated",
                }]),
                {
                    "label": "收回",
                    "hint": "收回此道准旨",
                    "dossier_id": dossier_id,
                    "dossier_decision": "withdrawn",
                },
                {
                    "label": "留中",
                    "hint": "留待下月重判",
                    "dossier_id": dossier_id,
                    "dossier_decision": "hold",
                },
            ],
        })
    return decisions

def qualitative_promulgation_slot(row: dict) -> str:
    """颁布格定性。强颁组合态保留「打回」本值，另由 stigma/标记位表达强颁。"""
    raw = _promulgation_decision_raw(row)
    # 强颁：颁布格 outcome 仍是打回（0052），brief 侧并列「强颁」标记。
    if raw == "force_promulgated":
        base = str(row.get("promulgation_decision") or "").strip()
        if base == "rejected":
            return DOSSIER_DECISION_CN["rejected"]
        return DOSSIER_DECISION_CN["force_promulgated"]
    return qualitative_dossier_decision(raw)

def render_referenceable_dossier_brief(candidates) -> str:
    """认账唯一 brief 渲染：status/颁布格/执行格/中旨标记一律定性中文。"""
    if not candidates:
        return ""
    lines = [
        "【可参考既有旨意（若有关联，请按标题或事项复述；勿向陛下念内部编号）】",
    ]
    for row in candidates:
        if not isinstance(row, dict):
            continue
        title = str(
            row.get("secret_title") or row.get("decree_text") or row.get("action_type") or ""
        )
        status_cn = qualitative_dossier_status(row.get("status"))
        decision_cn = qualitative_promulgation_slot(row)
        outcome_cn = qualitative_dossier_outcome(
            row.get("execution_outcome"), status=row.get("status"),
        )
        note = str(row.get("execution_note") or "")
        markers = qualitative_midzhi_markers(row)
        facts = []
        if status_cn:
            facts.append(f"状态：{status_cn}")
        if decision_cn:
            facts.append(f"颁布：{decision_cn}")
        if outcome_cn:
            facts.append(f"执行：{outcome_cn}")
        if note:
            facts.append(f"说明：{note}")
        if markers:
            facts.append("标记：" + "、".join(markers))
        fact_text = "；".join(facts)
        suffix = f"（{fact_text}）" if fact_text else ""
        lines.append(f"- [内部键 {int(row['id'])}] {title}{suffix}")
    return "\n".join(lines)

def experiences(self, affair_id: int) -> tuple[dict[str, object], ...]:
    """Read-time projection: story-ledger rows whose origin_ref points at this affair."""
    self.get(affair_id)
    refs = self.origin_refs(affair_id)
    affair_ref = self.origin_ref(affair_id)
    placeholders = ",".join("?" for _ in refs)
    rows = self._conn.execute(
        "SELECT id, person_names, tags, body, origin_ref "
        "FROM story_ledger_entries WHERE origin_ref IN ("
        + placeholders
        + ") OR origin_ref LIKE ? ORDER BY id",
        (*refs, f"{affair_ref}/%"),
    ).fetchall()
    out: list[dict[str, object]] = []
    for row in rows:
        origin = str(row["origin_ref"] or "").strip()
        try:
            tags = json.loads(row["tags"] or "[]")
        except (TypeError, ValueError):
            tags = []
        if not isinstance(tags, list):
            tags = []
        try:
            people = json.loads(row["person_names"] or "[]")
        except (TypeError, ValueError):
            people = []
        if not isinstance(people, list):
            people = []
        out.append({
            "id": int(row["id"]),
            "body": str(row["body"] or ""),
            "origin_ref": origin,
            "person_names": [str(name) for name in people if str(name).strip()],
            "tags": [str(tag) for tag in tags if str(tag).strip()],
        })
    return tuple(out)

def assert_target_locality_matrix(
    *,
    target_kind: object,
    locality_scope: object,
) -> str:
    """#654 / #1624：target_kind × locality_scope 8×3 矩阵唯一实现（无 DB）。

    可接受面真源 = TARGET_KIND_LOCALITY_SCOPES（#1778：national 不再另咬动作白名单）。
    resolve_dossier_region_ids 与 structured_decree 组合闸共引本函数——禁止平行第二份矩阵。
    失败带 TargetLocalityMatrixError.failed_fields（逐不变式可修边界）。
    """
    kind = str(target_kind or "").strip()
    kinds_expected = sorted(TARGET_KINDS)

    def _fact(
        field: str,
        *,
        current: object,
        expected: object,
    ) -> dict[str, object]:
        return {"field": field, "current": current, "expected": expected}

    def _matrix_fail(
        message: str,
        *,
        field_failures: tuple[dict[str, object], ...],
    ) -> None:
        raise TargetLocalityMatrixError(
            message,
            field_failures=field_failures,
        )

    try:
        scope = normalize_locality_scope(locality_scope)
    except ValueError as exc:
        _matrix_fail(
            str(exc),
            field_failures=(
                _fact(
                    "locality_scope",
                    current=locality_scope,
                    expected=sorted(LOCALITY_SCOPES),
                ),
            ),
        )

    allowed = TARGET_KIND_LOCALITY_SCOPES.get(kind)

    if allowed is None or kind not in TARGET_KINDS:
        _matrix_fail(
            f"target_kind 非法：{kind!r}",
            field_failures=(
                _fact("target_kind", current=kind, expected=kinds_expected),
            ),
        )

    scope_allowed = sorted(allowed)
    if scope not in allowed:
        # 保留历史失败措辞（下游测试/诊断认语义，不锁字符串为闸）
        kind_fact = _fact("target_kind", current=kind, expected=kinds_expected)
        scope_fact = _fact(
            "locality_scope", current=scope, expected=scope_allowed,
        )
        if kind == "region":
            _matrix_fail(
                f"region 目标与 locality_scope={scope!r} 矛盾（须 single）",
                field_failures=(scope_fact,),
            )
        if kind == "dossier":
            _matrix_fail(
                f"target_kind=dossier 与 locality_scope={scope!r} 矛盾（须 none）",
                field_failures=(scope_fact,),
            )
        if scope == "single":
            _matrix_fail(
                f"locality_scope=single 只配 region 目标，得 target_kind={kind!r}",
                field_failures=(scope_fact, kind_fact),
            )
        if scope == "national":
            _matrix_fail(
                f"target_kind={kind!r} 不得 national fan-out",

def project_target_locality_matrix_prompt() -> str:
    """由 TARGET_KIND_LOCALITY_SCOPES 投影可接受面（供共同 prompt 消费；禁手抄）。"""
    groups: Dict[frozenset[str], list[str]] = {}
    for kind, scopes in TARGET_KIND_LOCALITY_SCOPES.items():
        groups.setdefault(scopes, []).append(kind)
    parts: list[str] = []
    for scopes in sorted(groups, key=lambda s: (sorted(s), len(s))):
        kinds = "|".join(sorted(groups[scopes]))
        if len(scopes) == 1:
            only = next(iter(scopes))
            parts.append(f"{kinds}仅{only}")
        else:
            parts.append(f"{kinds}∈{'|'.join(sorted(scopes))}")
    return (
        "target_kind×locality_scope 可接受面（" + "；".join(parts) + "）"
    )

def classify_execution_coverage(
    action_type: object, payload: Optional[Mapping[str, object]] = None,
) -> Optional[str]:
    """只读 canonical 动作及结构化细类判别执行覆盖域，不解析旨文。"""
    action = str(action_type or "").strip()
    if action in _COVERAGE_APPOINTMENT:
        return "appointment"
    if action in _COVERAGE_MULTI_MONTH:
        return "multi_month"
    if action == "punishment":
        from ming_sim.action_clusters import cluster_by_kind

        punish_action = str((payload or {}).get("punish_action") or "").strip()
        cluster = cluster_by_kind("punishment")
        field = next((f for f in cluster.fields if f.name == "punish_action"), None) if cluster else None
        if field is not None and field.execution_coverage is not None:
            return field.execution_coverage.get(punish_action)
    return None

def _admit_transit_departure(
    item: Dict[str, object],
    row: Dict[str, object],
    valid_regions: set[str],
) -> tuple[Optional[Dict[str, object]], Optional[tuple[str, str]]]:
    """Return the canonical, write-free departure projection or its item rejection."""
    if "location" in item:
        return None, ("行止只接受 transit_to 启程", "invalid_transition")
    transit_to = str(item.get("transit_to") or "").strip()
    if not transit_to:
        return None, ("transit_to 缺失", "missing_field")
    if str(row.get("status") or "active") != "active":
        return None, ("行止 仅适用于 active 人物", "invalid_transition")
    if transit_to not in valid_regions:
        return None, ("transit_to 地区不存在", "missing_ref")
    try:
        tone = normalize_travel_tone(item.get("行程语气"))
    except ValueError:
        return None, ("行程语气不在闭合枚举", "invalid_enum")
    previous_destination = str(row.get("transit_to") or "")
    if previous_destination and previous_destination != transit_to:
        return None, ("在途人物不可改道", "invalid_transition")
    location = str(row.get("location") or "")
    if location not in valid_regions:
        return None, None
    matrix = DistanceMatrix.from_file(bundled_path("content", "distance_matrix.json"))
    distance = matrix.travel_time(location, transit_to)
    if not math.isfinite(distance) or distance < 0 or (location != transit_to and distance <= 0):
        raise ValueError(f"invalid baked travel time: {location!r} -> {transit_to!r}")
    terminal_location = transit_to if distance == 0 else location
    terminal_transit_to = "" if distance == 0 else transit_to
    return {
        "location": terminal_location,
        "transit_to": terminal_transit_to,
        "distance": distance,
        "tone": tone,
        "speed": None if distance == 0 else TRAVEL_SPEED_BY_TONE[tone],
        "material": (
            terminal_location != location
            or terminal_transit_to != previous_destination
        ),
    }, None

def _apply_dossier_participant_items(
    db: GameDB,
    state: GameState,
    extracted: Dict[str, object],
    *,
    items_key: str,
    authority_set: set,
    not_in_batch_msg: str,
) -> List[Dict[str, object]]:
    """Shared control flow for public/secret roster apply; fields stay separate.

    items_key / authority_set / not_in_batch_msg stay caller-owned — never union
    the two closed authority sets, never share a field-name or result slot.
    Missing authority is an empty closed set; never reconstruct from live DB.
    """
    results: List[Dict[str, object]] = []
    if not isinstance(authority_set, set):
        authority_set = set()
    for item in extracted.get(items_key) or []:
        if not isinstance(item, dict):
            results.append({
                "rejected": True, "category": "invalid_shape", "item": item,
            })
            continue
        try:
            dossier_id = _parse_sqlite_id(item.get("dossier_id"))
            if dossier_id not in authority_set:
                raise ValueError(not_in_batch_msg)
            character_id = str(item.get("character_id") or "").strip()
            delegator_id = str(item.get("delegator_id") or "").strip()
            tier = str(item.get("tier") or "").strip()
            if not character_id:
                raise ValueError("追加参与人物不能为空")
            if tier not in {"主办", "协办", "知情"}:
                raise ValueError("追加参与层级必须为主办/协办/知情")
            if not delegator_id:
                raise ValueError("追加参与人必须注明委派人")
            added = db.append_decree_dossier_participants(dossier_id, [{
                "character_id": character_id,
                "tier": tier,
                "role": str(item.get("role") or ""),
                "delegator_id": delegator_id,
            }], state=state, commit=False)
            if not added:
                # Exact durable duplicate is the only no-write success case.
                existing = db.get_decree_dossier(dossier_id) or {}
                if not any(
                    row.get("character_id") == character_id
                    and row.get("tier") == tier
                    and row.get("role") == str(item.get("role") or "")
                    and row.get("delegator_id") == delegator_id
                    for row in existing.get("participant_roster", [])
                ):
                    raise ValueError("参与人未实际加入案卷")
            persisted = added[0] if added else {
                "character_id": character_id, "tier": tier,
            }
            results.append({
                "dossier_id": dossier_id,
                "character_id": persisted["character_id"], "tier": persisted["tier"],
            })
        except (TypeError, ValueError, KeyError) as exc:
            results.append({
                "rejected": True, "category": "invalid_participant_roster",
                "reason": str(exc), "item": item,
            })
    return results

def _apply_ordinary_entity_step(
    step_extracted: Dict[str, object],
    step_ordered: Dict[str, list[tuple[str, object]]],
    step_event_ids: dict[str, list[str]],
) -> None:
    step_new_armies = step_extracted.get("new_armies") or []
    declared = step_event_ids.get("new_armies") or []
    for idx, army_item in enumerate(step_new_armies):
        if not isinstance(army_item, dict):
            continue
        event_for_item = declared[idx] if idx < len(declared) else ""
        if event_for_item in strategic_event_referenced_ids:
            continue
        origin_ref = str(army_item.get("origin_ref") or "").strip()
        created_armies.extend(db.create_armies_from_extraction(
            state, [army_item], actor="档房", commit=commit_now,
            origin_ref=origin_ref, require_origin=True,
        ))
    for index, (region_id, raw_changes) in enumerate(step_ordered.get("region_delta") or []):
        if _effect_event_ids(
            "region_delta", index, strategic_event_referenced_ids, step_event_ids,
        ):
            continue
        origin_ref = str(raw_changes.get("origin_ref") or "").strip()
        payload = {k: v for k, v in raw_changes.items() if k != "origin_ref"}
        region_changes.extend(db.apply_region_deltas(
            state, pseudo_event, None, "档房", {region_id: payload},
            commit=commit_now, origin_ref=origin_ref, require_origin=True,
        ))
    for index, (army_id, raw_changes) in enumerate(step_ordered.get("army_delta") or []):
        if _effect_event_ids(
            "army_delta", index, strategic_event_referenced_ids, step_event_ids,
        ):
            continue
        army_changes.extend(_apply_extracted_army_delta(
            db, state, pseudo_event, army_id, raw_changes, commit_now=commit_now,
        ))

def _commitment_arrears_gate_army_ids(row: sqlite3.Row) -> List[str]:
    ids: List[str] = []
    for key in _commitment_stop_gate(row):
        text = str(key)
        match = re.fullmatch(r"army\.([^.]+)\.arrears(?:\.sum)?", text)
        if not match:
            continue
        for army_id in match.group(1).split("|"):
            army_id = army_id.strip()
            if army_id and army_id not in ids:
                ids.append(army_id)
    return ids

def _gate_passed(gate: Dict[str, str], metrics: Dict[str, int], db: GameDB) -> bool:
    """trigger_gate 全部条件满足才返回 True。条件形如 '<=240'（数值）或 '==ming'（文本相等）。
    key 形式见 _eval_gate_key。gate=None（content JSON 显式 null）视同空门、恒过，不 .items()
    AttributeError 崩候选收集（PR#107 gemini；集中守 None，seed/历史两分支共用此函数同得保护）。
    """
    for key, cond in (gate or {}).items():
        cond = str(cond).strip()  # 非字符串条件值(JSON 漏引号写成 60/True)先 str 强转，不 .strip() 崩（PR#107 gemini）
        # 文本相等 / 枚举：==<word> / !=<word> / in=a|b（RHS 非纯数字）
        sm = re.match(r"^(==|!=|in=)\s*(.+)$", cond)
        if sm and (sm.group(1) == "in=" or not re.match(r"^-?\d+$", sm.group(2).strip())):
            sop, sval = sm.group(1), sm.group(2).strip()
            try:
                cur = _eval_gate_key_str(key, db)
            except sqlite3.OperationalError as exc:
                # typo'd 字段名 → SELECT 绑 SQLite 抛「no such column」；fail-loud 成清晰 content
                # 错误（#12 Q3：trigger_gate 字段错属静态 content schema 错）。其它 DB 错（锁/无表等）
                # 不误标字段，原样上抛（online sourcery）。
                if "no such column" in str(exc).lower():
                    raise ValueError(f"trigger_gate key「{key}」字段无效（DB 无此列）：{exc}") from exc
                raise
            if cur is None:
                return False
            if sop == "==" and cur != sval:
                return False
            if sop == "!=" and cur == sval:
                return False
            if sop == "in=" and cur not in {part.strip() for part in sval.split("|") if part.strip()}:
                return False
            continue
        m = re.match(r"^(>=|<=|>|<|==)\s*(-?\d+)$", cond)
        if not m:
            return False
        op, num = m.group(1), int(m.group(2))
        try:
            val = _eval_gate_key(key, metrics, db)
        except sqlite3.OperationalError as exc:
            if "no such column" in str(exc).lower():
                raise ValueError(f"trigger_gate key「{key}」字段无效（DB 无此列）：{exc}") from exc
            raise  # 其它 DB 错不误标字段（online sourcery）
        if val is None:
            return False
        if op == ">=" and not val >= num:
            return False
        if op == "<=" and not val <= num:
            return False
        if op == ">" and not val > num:
            return False
        if op == "<" and not val < num:
            return False
        if op == "==" and not val == num:
            return False
    return True

def _monthly_person_rating_changes(effect: Dict[str, object]) -> List[Dict[str, object]]:
    raw_changes: List[Dict[str, object]] = []
    for key in ("人物变更", "person_changes"):
        raw = effect.get(key)
        if isinstance(raw, list):
            raw_changes.extend(item for item in raw if isinstance(item, dict))
    changes = [
        item
        for item in normalize_person_changes({"人物变更": raw_changes})
        if isinstance(item, dict)
        and str(item.get("动作") or "").strip() == "评定"
        and not isinstance(item.get("loyalty"), bool)
        and isinstance(item.get("loyalty"), int)
        and int(item.get("loyalty") or 0) != 0
    ]
    raw_character = effect.get("character")
    if isinstance(raw_character, list):
        for item in raw_character:
            if not isinstance(item, dict):
                continue
            name = str(item.get("name") or item.get("人物") or "").strip()
            loyalty = item.get("loyalty")
            if not name or isinstance(loyalty, bool) or not isinstance(loyalty, int) or loyalty == 0:
                continue
            changes.append({
                "name": name,
                "动作": "评定",
                "loyalty": loyalty,
                "reason": str(item.get("reason") or item.get("原因") or ""),
            })
    return changes

def _payload_owned_dossier_for_origin(db: GameDB, origin_ref: object) -> Optional[Dict[str, object]]:
    """Resolve an authorized dossier through the canonical ownership policy."""
    text = str(origin_ref or "").strip()
    if not text.startswith("dossier:"):
        return None
    try:
        dossier_id = _parse_sqlite_id(text.split(":", 1)[1])
    except ValueError:
        return None
    row = db.get_decree_dossier(dossier_id)
    if row is None or not db.dossier_authorizes_effects(dossier_id):
        return None
    try:
        payload = row.get("payload") or json.loads(str(row.get("payload_json") or "{}"))
    except (TypeError, ValueError):
        return None
    if not isinstance(payload, dict):
        return None
    if dossier_action_policy(row.get("action_type"), payload)["effect_owner"] != "payload":
        return None
    return {**row, "payload": payload}

