def classify_transport_failure(error: BaseException) -> ClassifiedFailure:
    """先分类后重试。只认 typed 信号；不从错误散文猜语义（ADR 0142）。

    可重试：瞬断/空转/5xx/408/429/空输出；召对 429 例外在调用策略落实。
    不可重试：其余确定性 4xx（#1452 Unknown model 等带 4xx status）。
    未知（无 status 的笼统 stream/run error）→ 不洗成瞬断，立即上浮。

    本函数是 APITimeout/Connection/Status/空输出/RunError → code/retryable/status 的唯一权威
    （llm_unavailable_from_error / run_error_event_failure / empty_output_failure 委派或同构）。
    """
    if isinstance(error, TransportIdleTimeout):
        return ClassifiedFailure(
            retryable=True,
            code="llm_idle_timeout",
            status_code=None,
            provider_message=str(error) or "idle timeout",
            message="LLM 调用空转超时。",
        )
    if isinstance(error, APITimeoutError):
        return ClassifiedFailure(
            retryable=True,
            code="llm_timeout",
            status_code=None,
            provider_message=str(error),
            message="LLM 调用超时。",
        )
    if isinstance(error, APIConnectionError):
        return ClassifiedFailure(
            retryable=True,
            code="llm_connection_error",
            status_code=None,
            provider_message=str(error),
            message="LLM 连接失败。",
        )
    if isinstance(error, APIStatusError):
        status_i = _coerce_status(getattr(error, "status_code", None))
        code = f"llm_http_{status_i}" if status_i is not None else "llm_http_error"
        return ClassifiedFailure(
            retryable=_status_retryable(status_i),
            code=code,
            status_code=status_i,
            provider_message=str(error),
            message=f"LLM 调用失败（HTTP {status_i}）。" if status_i else "LLM 调用失败。",
        )
    if isinstance(error, LLMUnavailable):
        status = error.status_code
        code = str(error.code or "llm_unavailable")
        pmsg = str(error.provider_message or error.message or "")
        status_i = _coerce_status(status)
        if status_i is not None:
            return ClassifiedFailure(
                retryable=_status_retryable(status_i),
                code=code,
                status_code=status_i,
                provider_message=pmsg,
                message=str(error.message or pmsg or "LLM 调用失败。"),
            )
        if code in {
            "llm_timeout",
            "llm_connection_error",
            "llm_idle_timeout",
            "llm_empty_output",
        }:
            return ClassifiedFailure(
                retryable=True,
                code=code,
                status_code=None,
                provider_message=pmsg,
                message=str(error.message or pmsg or "LLM 调用失败。"),
            )
        if code.startswith("llm_http_"):
            tail = code[len("llm_http_") :]
            status_from_code = _coerce_status(tail)
            if status_from_code is not None:
                return ClassifiedFailure(
                    retryable=_status_retryable(status_from_code),
                    code=code,
                    status_code=status_from_code,
                    provider_message=pmsg,
                    message=str(error.message or pmsg or "LLM 调用失败。"),
                )

def resolve_special_region_alias(token: str) -> Optional[str]:
    """Exact id or special-alias token → region_id；未知返回 None（不模糊匹配）。"""
    raw = str(token or "").strip()
    if not raw:
        return None
    if raw in REGION_SPECIAL_ALIASES:
        return raw
    key = compact_name(raw)
    if not key:
        return None
    if key in REGION_SPECIAL_ALIASES:
        return key
    for region_id, aliases in REGION_SPECIAL_ALIASES.items():
        if key == compact_name(region_id):
            return region_id
        for alias in aliases:
            if key == compact_name(alias):
                return region_id
    return None

def _scene_opening_text(
    state: Any,
    present_rows: Sequence[tuple[str, str]],
    spoken: str,
    handling_by_person: Sequence[tuple[str, Sequence[tuple[str, str]]]],
    pending_audience_facts: Sequence[str] = (),
) -> str:
    """场景 LLM 开场最小集（ADR 0155）：在场、日期、正经手、本场已说、当前待裁场面。"""
    if present_rows:
        present_line = "、".join(
            f"{name}（{office}）" if office else name for name, office in present_rows
        )
    else:
        present_line = "（尚无）"
    parts = [
        f"在场：{present_line}",
        f"日期：{int(state.year)}年{int(state.period)}月",
    ]
    # 各在场人正经手事务（名字 + 当前情况一句）；无人经手则标（无）。
    parts.append("正经手事务：")
    any_handling = False
    for name, affairs in handling_by_person:
        if not affairs:
            continue
        any_handling = True
        parts.append(f"{name}：")
        parts.extend(f"- {title}：{situation}" for title, situation in affairs)
    if not any_handling:
        parts.append("（无）")
    parts.append("本场已说的话：")
    parts.append(spoken if spoken.strip() else "（尚无）")
    # #1838 reopen / ADR 0155：当前待裁场面（到期复命、暗渠摊派暴露/缺口重开）
    parts.append("当前待裁场面：")
    if pending_audience_facts:
        parts.extend(str(line) for line in pending_audience_facts)
    else:
        parts.append("（无）")
    parts.append(
        "在场诸人各自材料在 人物/<名>/ 下（人物档料、经历、公事档案、朝臣名册、事务、公开说法）。"
        "根目录 INDEX 一行一项。其余想读自己读。"
    )
    return "\n".join(parts)

def dossier_id_in_origin(origin: object) -> Optional[int]:
    text = str(origin or "")
    if not text.startswith("dossier:"):
        return None
    raw = text[len("dossier:"):].split(":", 1)[0]
    if not raw.isdigit():
        return None
    return int(raw)

def is_secret_order_origin(origin: object) -> bool:
    """是否密令来源：origin/source_id 以 SECRET_ORDER_ORIGIN_PREFIX 开头。"""
    return str(origin or "").startswith(SECRET_ORDER_ORIGIN_PREFIX)

def _person_effect_has_work(raw: object) -> bool:
    if not isinstance(raw, list):
        return False
    for item in raw:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name") or item.get("人物") or "").strip()
        action = str(item.get("动作") or item.get("action") or "").strip()
        if not name or action not in PERSON_ACTIONS:
            continue
        if action == "评定":
            loyalty = item.get("loyalty")
            if (
                not isinstance(loyalty, bool)
                and isinstance(loyalty, int)
                and loyalty != 0
            ):
                return True
            continue
        if action == "性情":
            style = item.get("style")
            if isinstance(style, str) and style.strip():
                return True
            continue
        return True
    return False

def _dossier_for_decree_ref(db: Any, decree_ref: str) -> Optional[Dict[str, Any]]:
    from ming_sim.decree_forecast import decree_ref_for_dossier

    for dossier in db.list_decree_dossiers():
        if decree_ref_for_dossier(db, dossier) == decree_ref:
            return dossier
    if decree_ref.startswith("dossier:"):
        raw = decree_ref.split(":", 1)[1]
        if raw.isdigit():
