def compose_report_origin(base: str, marks: Iterable[str] = ()) -> str:
    """结构化 origin：base[+mark...]。base 须已带 dossier-report: 前缀。"""
    cleaned = [str(m).strip() for m in marks if str(m or "").strip()]
    # 去重保序
    seen: Set[str] = set()
    ordered: List[str] = []
    for mark in cleaned:
        if mark in seen:
            continue
        seen.add(mark)
        ordered.append(mark)
    root = str(base or "").strip()
    if not ordered:
        return root
    return root + ORIGIN_MARK_SEP + ORIGIN_MARK_SEP.join(ordered)

def axis_collision_stances(
    collisions: Iterable[Mapping[str, object]],
    *,
    target_faction: object,
) -> list[dict[str, object]]:
    """逐格读取目标感知撞轴集的 ``stance × direction``。"""
    target = str(target_faction or "").strip()
    factions = _loaded()[1]
    results: list[dict[str, object]] = []
    for collision in collisions:
        axis = normalize_axis(collision.get("axis"))
        scope = collision.get("scope")
        if axis is None:
            continue
        direction = normalize_direction(collision.get("direction"), default=1)
        if scope == "泛化":
            recipients = (
                faction for faction in factions if faction_axis_stance(faction, axis) != 0
            )
        elif scope == "目标命门" and target in factions:
            recipients = (target,)
        else:
            continue
        for faction in recipients:
            results.append(
                {
                    "faction": faction,
                    "axis": axis,
                    "direction": direction,
                    "scope": scope,
                    "aligned_stance": faction_axis_stance(faction, axis) * direction,
                }
            )
    return results

def faction_axis_stance(faction: object, axis: object) -> int:
    """读矩阵格；未知派/轴 → 0（中性，不发明）。"""
    fac = str(faction or "").strip()
    ax = normalize_axis(axis)
    if not fac or ax is None:
        return 0
    row = _loaded()[1].get(fac)
    if row is None:
        return 0
    return int(row.get(ax, 0))

def ask_emperor(agent: Agent, cli_chunk: str, prompt_hint: str, progress: str = "") -> tuple[str, str]:
    # progress：本月进度提示（已问几轮/已下旨几条/还差啥）。num_history_runs 只留近 8 轮，
    # agent 看不到完整本月动作易盲凑、重复召见，故每步显式喂进度，让它知道走到哪、该收尾还是继续。
    payload = (
        f"{progress}\n\n" if progress else ""
    ) + (
        f"CLI 当前输出（最新一段）：\n```\n{cli_chunk[-3500:]}\n```\n\n"
        f"当前等待输入的 prompt 是：{prompt_hint}\n\n"
        f"请输出下一条键盘输入（严格 JSON）。"
    )
    response = agent.run(payload)
    raw = response.content if hasattr(response, "content") else str(response)
    if isinstance(raw, list):
        raw = "".join(str(item) for item in raw)
    return parse_emperor_output(str(raw))

